Below is the complete Terraform HCL program that configures a query log for Route 53, creating a log stream and putting log events into a specified CloudWatch log group. The program includes the necessary IAM roles and policies to enable Route 53 to write query logs to CloudWatch.

```hcl
provider "aws" {
  region = "us-east-1"  # Specify your desired AWS region
}

resource "aws_route53_zone" "primary" {
  name = "example.com"
}

resource "aws_cloudwatch_log_group" "aws_route53_example_com" {
  name = "/aws/route53/example.com"
}

resource "aws_iam_role" "route53_query_logging_role" {
  name = "route53-query-logging-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "route53.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "route53_query_logging_policy" {
  name = "route53-query-logging-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "${aws_cloudwatch_log_group.aws_route53_example_com.arn}:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_route53_query_logging_policy" {
  policy_arn = aws_iam_policy.route53_query_logging_policy.arn
  role       = aws_iam_role.route53_query_logging_role.name
}

resource "aws_route53_query_log" "example_com_query_log" {
  cloudwatch_log_group_arn = aws_cloudwatch_log_group.aws_route53_example_com.arn
  zone_id                  = aws_route53_zone.primary.zone_id
}
```

This Terraform configuration ensures that all dependencies are correctly handled and that the necessary resources are created in the correct order. The `aws_route53_zone` creates the DNS zone, the `aws_cloudwatch_log_group` sets up the log group, the `aws_iam_role` and `aws_iam_policy` define the necessary permissions, and the `aws_route53_query_log` links everything together.

