Below is a complete Terraform HCL program that configures Route 53 to return different database endpoints to internal versus external users. The program creates two Route 53 zones ("private" and "public"), a DB subnet group ("main"), and two RDS instances ("internal" and "public"). It also creates Route 53 records pointing to these RDS instances.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "main" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "main-subnet-${count.index}"
  }
}

resource "aws_db_subnet_group" "main_subnet_group" {
  name       = "main"
  subnet_ids = aws_subnet.main[*].id

  tags = {
    Name = "main-subnet-group"
  }
}

resource "aws_security_group" "internal_db_sg" {
  name        = "internal-db-sg"
  description = "Security group for internal DB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "internal-db-sg"
  }
}

resource "aws_security_group" "public_db_sg" {
  name        = "public-db-sg"
  description = "Security group for public DB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "public-db-sg"
  }
}

resource "aws_db_instance" "internal_db" {
  identifier           = "internal-db"
  instance_class       = "db.t3.micro"
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
