Below is the complete Terraform HCL program that configures Route 53 resources to manage a domain and directs traffic to an Elastic Beanstalk environment, following the specified requirements and dependencies.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_route53_zone" "main" {
  name = "example.com"
}

resource "aws_s3_bucket" "unique_bucket_name" {
  bucket = "my-unique-bucket-name-for-app-version"
  acl    = "private"
}

resource "aws_s3_bucket_object" "examplebucket_object" {
  bucket = aws_s3_bucket.unique_bucket_name.id
  key    = "application-version.zip"
  source = "./application-version.zip"
}

resource "aws_iam_role" "eb_ec2_role" {
  name = "eb_ec2_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_instance_profile" "eb_ec2_profile" {
  name = "eb_ec2_profile"
  role = aws_iam_role.eb_ec2_role.name
}

resource "aws_elastic_beanstalk_application" "myapp" {
  name = "myapp"
}

resource "aws_elastic_beanstalk_application_version" "version" {
  application = aws_elastic_beanstalk_application.myapp.name
  bucket      = aws_s3_bucket.unique_bucket_name.id
  key         = aws_s3_bucket_object.examplebucket_object.key
  name        = "v1.0.0"
}

resource "aws_elastic_beanstalk_environment" "eb_env" {
  application = aws_elastic_beanstalk_application.myapp.name
  name        = "eb-env"
  version_label = aws_elastic_beanstalk_application_version.version.name
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 14"
  instance_profile = aws_iam_instance_profile.eb_ec2_profile.name
}

resource "aws_route53_record" "eb_env_record" {
  zone_id = aws_route53_zone.main.zone_id
  name    = "www.example.com"
  type    = "A"

  alias {
    name                   = aws_elastic_beanstalk_environment.eb_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eb_env.endpoint_url
    evaluate_target_health = true
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Route 53 Zone**: A Route 53 hosted zone named `example.com` is created.
- **S3 Bucket**: A unique S3 bucket named `my-unique-bucket-name-for-app-version` is created to store the application version.
- **S3 Bucket Object**: An S3 bucket object named `application-version.zip` is uploaded to the S3 bucket.
- **IAM Role and Instance Profile**: An IAM role named `eb_ec2_role` is created with a trust relationship for EC2 instances. An IAM instance profile named `eb_ec2_profile` is associated with this role.
- **Elastic Beanstalk Application**: An Elastic Beanstalk application named `myapp` is created.
- **Elastic Beanstalk Application Version**: An application version named `v1.0.0` is created using the uploaded S3 object.
- **Elastic Beanstalk Environment**: An Elastic Beanstalk environment named `eb-env` is created using the application version and instance profile.
- **Route 53 Record**: A Route 53 record named `www.example.com` is created to direct traffic to the Elastic Beanstalk environment using an alias record.

This configuration ensures that all dependencies are correctly handled and all resources are properly defined and referenced.

