Below is a complete Terraform HCL program that sets up a Blue/Green deployment using AWS Elastic Beanstalk and Route53 with a Weighted Routing Policy. The program includes the creation of two Elastic Beanstalk environments named "blue" and "green", and corresponding Route53 records for weighted traffic distribution.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_elastic_beanstalk_application" "app" {
  name        = "my-blue-green-app"
  description = "Application for Blue/Green Deployment"
}

resource "aws_elastic_beanstalk_environment" "blue_environment" {
  application = aws_elastic_beanstalk_application.app.name
  name        = "blue"
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label     = "v1"
  tier              = "WebServer"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceType"
    value     = "t3.micro"
  }
}

resource "aws_elastic_beanstalk_environment" "green_environment" {
  application = aws_elastic_beanstalk_application.app.name
  name        = "green"
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Node.js 16"
  version_label     = "v1"
  tier              = "WebServer"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceType"
    value     = "t3.micro"
  }
}

resource "aws_route53_zone" "primary_zone" {
  name = "example.com"
}

resource "aws_route53_record" "weighted_routing_record_blue" {
  zone_id = aws_route53_zone.primary_zone.id
  name    = "app.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.blue_environment.cname
    zone_id                = aws_elastic_beanstalk_environment.blue_environment.endpoint_url
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "weighted_routing_record_green" {
  zone_id = aws_route53_zone.primary_zone.id
  name    = "app.example.com"
  type    = "A"
  ttl     = 300

  weighted_routing_policy {
    weight = 50
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.green_environment.cname
    zone_id                = aws_elastic_beanstalk_environment.green_environment.endpoint_url
    evaluate_target_health = true
  }
}
```

### Explanation:
- **Provider Configuration**: Configures the AWS provider to use the `us-west-2` region.
- **Elastic Beanstalk Application**: Creates an Elastic Beanstalk application named `my-blue-green-app`.
- **Elastic Beanstalk Environments**: Creates two environments, `blue` and `green`, both using the same application and settings.
- **Route53 Zone**: Creates a Route53 hosted zone for `example.com`.
- **Route53 Records**: Creates two A records for `app.example.com` with a weighted routing policy, directing traffic to the respective Elastic Beanstalk environments.

This configuration ensures that traffic is evenly distributed between the "blue" and "green" environments using a weighted routing policy in Route53. Adjust the `solution_stack_name`, `version_label`, and `zone_id` as necessary for your specific use case.

