}

resource "aws_elastic_beanstalk_application" "elastic_beanstalk_app" {
  name        = "my-elastic-beanstalk-app"
  description = "Application for hosting web applications"
}

resource "aws_elastic_beanstalk_environment" "us_west_env" {
