  solution_stack_name = "64bit Amazon Linux 2 v5.8.0 running Node.js 16"
  version_label     = "v1"
  tier              = "WebServer"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceType"
    value     = "t3.micro"
  }
}

provider "aws" {
  alias  = "eu-central"
  region = "eu-central-1"
}

resource "aws_elastic_beanstalk_environment" "eu_central_env" {
  provider = aws.eu-central

  application = aws_elastic_beanstalk_application.elastic_beanstalk_app.name
  name        = "eu_central"
  solution_stack_name = "64bit Amazon Linux 2 v5.8.0 running Node.js 16"
  version_label     = "v1"
  tier              = "WebServer"

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MinSize"
    value     = "1"
  }

  setting {
    namespace = "aws:autoscaling:asg"
    name      = "MaxSize"
    value     = "2"
  }

  setting {
    namespace = "aws:ec2:instances"
    name      = "InstanceType"
    value     = "t3.micro"
  }
}

resource "aws_route53_health_check" "us_west_health_check" {
  type                    = "HTTP"
  fqdn                    = aws_elastic_beanstalk_environment.us_west_env.cname
  port                    = 80
  resource_path           = "/"
  request_interval        = 30
  failure_threshold       = 3
  measure_latency         = true
  insufficient_data_health_status = "Healthy"
}

resource "aws_route53_health_check" "eu_central_health_check" {
  type                    = "HTTP"
  fqdn                    = aws_elastic_beanstalk_environment.eu_central_env.cname
  port                    = 80
  resource_path           = "/"
  request_interval        = 30
  failure_threshold       = 3
  measure_latency         = true
  insufficient_data_health_status = "Healthy"
}

variable "hosted_zone_id" {
  description = "The ID of the Route53 hosted zone"
  default     = "Z1234567890ABCDEF" # Replace with your actual hosted zone ID
}

resource "aws_route53_record" "geolocation_us_west_record" {
  zone_id = var.hosted_zone_id
  name    = "example.com"
  type    = "A"
  ttl     = 300

  geolocation_routing_policy {
    continent = "NA"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.us_west_env.cname
    zone_id                = aws_elastic_beanstalk_environment.us_west_env.endpoint_url
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "geolocation_eu_central_record" {
  zone_id = var.hosted_zone_id
  name    = "example.com"
  type    = "A"
  ttl     = 300

  geolocation_routing_policy {
    continent = "EU"
  }

  alias {
    name                   = aws_elastic_beanstalk_environment.eu_central_env.cname
    zone_id                = aws_elastic_beanstalk_environment.eu_central_env.endpoint_url
    evaluate_target_health = true
  }
}
```

### Explanation:
- **Provider Configuration**: The `aws` provider is configured for both `us-west-2` and `eu-central-1` regions.
- **Elastic Beanstalk Application**: A base application named `my-elastic-beanstalk-app` is created.
- **Elastic Beanstalk Environments**: Two environments (`us_west_env` and `eu_central_env`) are created in their respective regions.
- **Route53 Health Checks**: Health checks are created for both environments to monitor their availability.
- **Route53 Records**: Geolocation-based Route53 records are created to route traffic to the closest environment based on the user's location. The `zone_id` variable is used to specify the hosted zone ID where these records will be created.

Make sure to replace the `default` value of `hosted_zone_id` with your actual Route53 hosted zone ID before deploying this configuration.

