Below is the complete Terraform HCL program that provisions the necessary AWS infrastructure for deploying a web application, including IAM roles, a VPC with an Internet Gateway, two subnets, route configurations, and an RDS instance, all set up within an Elastic Beanstalk environment.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "web_app_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "web-app-vpc"
  }
}

resource "aws_internet_gateway" "web_app_igw" {
  vpc_id = aws_vpc.web_app_vpc.id
  tags = {
    Name = "web-app-igw"
  }
}

resource "aws_subnet" "web_app_subnet_1" {
  vpc_id                  = aws_vpc.web_app_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "web-app-subnet-1"
  }
}

resource "aws_subnet" "web_app_subnet_2" {
  vpc_id                  = aws_vpc.web_app_vpc.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2b"
  tags = {
    Name = "web-app-subnet-2"
  }
}

resource "aws_route_table" "web_app_route_table" {
  vpc_id = aws_vpc.web_app_vpc.id
  tags = {
    Name = "web-app-route-table"
  }
}

resource "aws_route" "web_app_route_to_igw" {
  route_table_id         = aws_route_table.web_app_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.web_app_igw.id
}

resource "aws_route_table_association" "web_app_subnet_1_assoc" {
  subnet_id      = aws_subnet.web_app_subnet_1.id
  route_table_id = aws_route_table.web_app_route_table.id
}

resource "aws_route_table_association" "web_app_subnet_2_assoc" {
  subnet_id      = aws_subnet.web_app_subnet_2.id
  route_table_id = aws_route_table.web_app_route_table.id
}

resource "aws_db_subnet_group" "web_app_db_subnet_group" {
  subnet_ids = [aws_subnet.web_app_subnet_1.id, aws_subnet.web_app_subnet_2.id]
  name       = "web-app-db-subnet-group"
  tags = {
    Name = "web-app-db-subnet-group"
  }
}

resource "aws_db_instance" "web_app_rds_instance" {
  instance_class     = "db.t3.micro"
  allocated_storage  = 20
  engine             = "mysql"
  engine_version     = "8.0"
  name               = "webappdb"
  username           = "admin"
  password           = "password123"
  db_subnet_group_name = aws_db_subnet_group.web_app_db_subnet_group.name
  skip_final_snapshot  = true
  tags = {
    Name = "web-app-rds-instance"
  }
