Below is the complete Terraform HCL program that creates an Elastic Beanstalk application running a version of Go. The program includes all necessary resources and dependencies as per the provided graph and schema summary.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elastic_beanstalk_service_role" {
  name = "elastic-beanstalk-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticbeanstalk.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "attach_elastic_beanstalk_policy" {
  name       = "attach-elastic-beanstalk-policy"
  roles      = [aws_iam_role.elastic_beanstalk_service_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSElasticBeanstalkFullAccess"
}

resource "aws_elastic_beanstalk_application" "go_app" {
  name = "go-app"

  appversion_lifecycle {
    service_role         = aws_iam_role.elastic_beanstalk_service_role.arn
    max_age_in_days      = 30
    delete_source_from_s3 = true
  }
}

resource "aws_s3_bucket" "go_app_bucket" {
  bucket = "go-app-bucket-unique-name"
}

resource "aws_s3_bucket_object" "go_app_version" {
  bucket = aws_s3_bucket.go_app_bucket.id
  key    = "go-app-version.zip"
  source = "./path/to/go-app-version.zip" # Ensure this file exists locally or adjust the path accordingly
}

resource "aws_elastic_beanstalk_application_version" "go_app_version" {
  application = aws_elastic_beanstalk_application.go_app.name
  bucket      = aws_s3_bucket.go_app_bucket.id
  key         = aws_s3_bucket_object.go_app_version.key
  name        = "go-app-version-1"
}

resource "aws_elastic_beanstalk_environment" "go_app_env" {
  application = aws_elastic_beanstalk_application.go_app.name
  name        = "go-app-env"
  solution_stack_name = "64bit Amazon Linux 2 v5.7.0 running Go 1.x"
  version_label = aws_elastic_beanstalk_application_version.go_app_version.name
}
```

### Explanation:
- **Provider Configuration**: Configured to use the AWS provider with the `us-west-2` region.
- **IAM Role**: Created an IAM role named `elastic-beanstalk-service-role` with a trust relationship to allow Elastic Beanstalk to assume the role.
- **IAM Policy Attachment**: Attached the `AWSElasticBeanstalkFullAccess` policy to the IAM role.
- **Elastic Beanstalk Application**: Created an Elastic Beanstalk application named `go-app` with lifecycle settings.
- **S3 Bucket**: Created an S3 bucket named `go-app-bucket-unique-name` to store the Go application version source code.
- **S3 Bucket Object**: Uploaded the Go application version source code to the S3 bucket.
- **Elastic Beanstalk Application Version**: Created an application version using the uploaded source code in the S3 bucket.
- **Elastic Beanstalk Environment**: Created an environment to run the Go application version using the specified solution stack.

Ensure that the `source` attribute in the `aws_s3_bucket_object` resource points to a valid local path where your Go application version zip file is located. Adjust the path as necessary.

