Below is the complete Terraform HCL program that provisions the necessary resources to deploy and scale a web application using AWS services. This includes setting up an IAM role, policy, and attachment, a launch template, an autoscaling group, a security group, an ELB, a route table, a subnet, and a VPC.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "web_app_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "web-app-vpc"
  }
}

resource "aws_subnet" "web_app_subnet" {
  vpc_id                  = aws_vpc.web_app_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "web-app-subnet"
  }
}

resource "aws_route_table" "web_app_route_table" {
  vpc_id = aws_vpc.web_app_vpc.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.web_app_igw.id
  }

  tags = {
    Name = "web-app-route-table"
  }
}

resource "aws_internet_gateway" "web_app_igw" {
  vpc_id = aws_vpc.web_app_vpc.id

  tags = {
    Name = "web-app-igw"
  }
}

resource "aws_security_group" "web_app_security_group" {
  vpc_id = aws_vpc.web_app_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 443
    to_port     = 443
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "web-app-security-group"
  }
}

resource "aws_iam_role" "web_app_role" {
  name = "web-app-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "web-app-role"
  }
}

resource "aws_iam_policy" "web_app_policy" {
  name = "web-app-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "web-app-policy"
  }
}

resource "aws_iam_role_policy_attachment" "attach_web_app_policy" {
  policy_arn = aws_iam_policy.web_app_policy.arn
  role       = aws_iam_role.web_app_role.name
}

resource "aws_launch_template" "web_app_launch_template" {
  name = "web-app-launch-template"

  iam_instance_profile {
    name = aws_iam_instance_profile.web_app_instance_profile.name
  }

  instance_type = "t3.micro"

  network_interfaces {
    associate_public_ip_address = true
    security_groups             = [aws_security_group.web_app_security_group.id]
  }

  tags = {
    Name = "web-app-launch-template"
  }
}

resource "aws_iam_instance_profile" "web_app_instance_profile" {
  name = "web-app-instance-profile"
  role = aws_iam_role.web_app_role.name
}

resource "aws_autoscaling_group" "web_app_autoscaling_group" {
  name                      = "web-app-autoscaling-group"
  launch_template           = { id = aws_launch_template.web_app_launch_template.id }
  vpc_zone_identifier       = [aws_subnet.web_app_subnet.id]
  min_size                  = 1
  max_size                  = 3
  desired_capacity          = 2
  health_check_grace_period = 300
  health_check_type         = "ELB"

  tag {
    key                 = "Name"
    value               = "web-app-instance"
    propagate_at_launch = true
  }

  tags = {
    Name = "web-app-autoscaling-group"
  }
}

resource "aws_elb" "web_app_load_balancer" {
  name            = "web-app-load-balancer"
  subnets         = [aws_subnet.web_app_subnet.id]
  security_groups = [aws_security_group.web_app_security_group.id]

  listener {
    instance_port     = 80
    instance_protocol = "http"
    lb_port           = 80
    lb_protocol       = "http"
  }

  health_check {
    healthy_threshold   = 2
    unhealthy_threshold = 2
    timeout             = 30
    interval            = 30
    target              = "HTTP:80/"
  }

  tags = {
    Name = "web-app-load-balancer"
  }
}
```

This Terraform configuration sets up a basic infrastructure for deploying and scaling a web application using EC2, Auto Scaling, and Elastic Load Balancing. It includes all necessary dependencies and ensures that all resources are correctly referenced and created in the correct order.

