```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lex_bot_role" {
  name = "lex-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lex.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lex_bot_policy" {
  name = "lex-bot-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lex_bot_policy" {
  policy_arn = aws_iam_policy.lex_bot_policy.arn
  role       = aws_iam_role.lex_bot_role.name
}

resource "aws_lex_bot" "my_lex_bot" {
  name               = "my-lex-bot"
  child_directed     = false
  description        = "My Lex Bot"
  detect_sentiment   = true
  enable_model_improvements = true
  idle_session_ttl_in_seconds = 300
  locale             = "en-US"
  nlu_intent_confidence_threshold = 0.7
  process_behavior   = "BUILD"
  voice_id           = "Joanna"

  clarification_prompt {
    max_attempts = 3
  }

  depends_on = [aws_iam_role_policy_attachment.attach_lex_bot_policy]
}
```

