```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_role" "lex_lambda_execution_role" {
  name = "lex_lambda_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lex_lambda_policy" {
  name = "lex_lambda_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lex_lambda_policy" {
  policy_arn = aws_iam_policy.lex_lambda_policy.arn
  role       = aws_iam_role.lex_lambda_execution_role.name
}

resource "aws_lambda_function" "pizza_ordering_lambda" {
  function_name = "pizza_ordering_lambda"
  role          = aws_iam_role.lex_lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  code = {
    zipfile = filebase64("${path.module}/pizza_ordering_lambda.zip")
  }
}

resource "aws_lex_intent" "order_pizza_intent" {
  name               = "OrderPizzaIntent"
  create_version     = true
  description        = "Intent to order pizza"
  sample_utterances  = ["I want to order a pizza", "Can I order a pizza"]

  fulfillment_activity {
    type = "CodeHook"

    code_hook {
      uri            = aws_lambda_function.pizza_ordering_lambda.invoke_arn
      message_version = "1.0"
    }
  }

  slot {
    name            = "PizzaType"
    slot_constraint = "Required"
    slot_type       = "AMAZON.FoodEstablishmentType"
  }

  slot {
    name            = "Quantity"
    slot_constraint = "Required"
    slot_type       = "AMAZON.NUMBER"
  }
}

resource "aws_lex_bot" "pizza_ordering_bot" {
  name               = "PizzaOrderingBot"
  child_directed     = false
  create_version     = true
  description        = "Bot to order pizza"
  locale             = "en-US"
  process_behavior   = "BUILD"

  intent {
    intent_name    = aws_lex_intent.order_pizza_intent.name
    intent_version = aws_lex_intent.order_pizza_intent.version
  }

  clarification_prompt {
    max_attempts = 3

    message {
      content_type = "PlainText"
      content      = "I didn't understand that. Can you please repeat?"
    }
  }

  abort_statement {
    message {
      content_type = "PlainText"
      content      = "Okay, let's start over."
    }
  }
}
```

### Notes:
- The `pizza_ordering_lambda.zip` file should contain the Lambda function code. Ensure this file exists in the same directory as your Terraform configuration.
- The `aws_lex_intent` resource includes slots for `PizzaType` and `Quantity` to capture the type and quantity of the pizza ordered.
- The `aws_lex_bot` resource includes a `clarification_prompt` and an `abort_statement` to handle user interactions more effectively.
- The `aws_iam_role` and `aws_iam_policy` resources ensure that the Lambda function has the necessary permissions to log to CloudWatch.

