provider "aws" {
  region = "us-west-2"
}

# Define a default IAM role for the Connect bot
resource "aws_iam_role" "connect_bot_role" {
  name = "connect-bot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "connect.amazonaws.com"
        }
      }
    ]
  })

  # Attach a basic policy for demonstration purposes
  managed_policy_arns = ["arn:aws:iam::aws:policy/AmazonConnectFullAccess"]
}

# Attach the necessary policy to the IAM role
resource "aws_iam_policy_attachment" "connect_bot_policy_attachment" {
  name       = "connect-bot-policy-attachment"
  roles      = [aws_iam_role.connect_bot_role.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonLexReadOnly"
}

# Associate the bot with the Connect instance using the configured IAM role
resource "aws_connect_bot_association" "bot_association" {
  instance_id = "arn:aws:connect:us-west-2:123456789012:instance/abcd1234-abcd-1234-abcd-1234abcd1234"

  lex_bot {
    name = "MyLexBot"
    lex_region = "us-west-2"
  }
}
```

