Below is the complete Terraform HCL program that creates an Amazon Kinesis Analytics Application with an input Kinesis stream. The program includes the necessary IAM role and policy to allow the Kinesis Analytics application to access the Kinesis stream.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_kinesis_stream" "input_stream" {
  name        = "example-input-stream"
  shard_count = 1
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_access_policy" {
  name = "kinesis-access-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:DescribeStream",
          "kinesis:ListStreams"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_stream.input_stream.arn
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kinesis_access_policy" {
  policy_arn = aws_iam_policy.kinesis_access_policy.arn
  role       = aws_iam_role.kinesis_analytics_role.name
}

resource "aws_kinesis_analytics_application" "analytics_app" {
  name = "example-analytics-app"

  inputs {
    name_prefix = "SOURCE_SQL_STREAM"
    kinesis_stream {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }
    parallelism {
      count = 1
    }
    schema {
      record_format {
        record_format_type = "JSON"
        mapping_parameters {
          json_mapping_parameters {
            record_row_path = "$"
          }
        }
      }
      record_encoding = "UTF-8"
    }
  }
}
```

This Terraform configuration sets up the following resources:
1. An AWS Kinesis Stream named `example-input-stream`.
2. An IAM Role named `kinesis-analytics-role` with a trust relationship to allow Kinesis Analytics to assume the role.
3. An IAM Policy named `kinesis-access-policy` that grants the necessary permissions to read from the Kinesis stream.
4. An attachment of the IAM Policy to the IAM Role.
5. A Kinesis Analytics Application named `example-analytics-app` that uses the Kinesis stream as its input source.

The configuration ensures that all dependencies are correctly handled and that the resources are created in the specified AWS region (`us-west-2`).

