Below is the complete Terraform HCL program that creates an Amazon Kinesis V2 Analytics Application to manage an Apache Flink Application. This configuration includes the necessary IAM roles, policies, and a Kinesis stream.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kinesis_analytics_role" {
  name = "kinesis-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kinesisanalytics.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_analytics_policy" {
  name = "kinesis-analytics-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "kinesis:GetRecords",
          "kinesis:GetShardIterator",
          "kinesis:DescribeStream",
          "kinesis:ListStreams",
          "logs:PutLogEvents",
          "logs:DescribeLogStreams",
          "logs:CreateLogGroup",
          "logs:CreateLogStream"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kinesis_analytics_policy" {
  policy_arn = aws_iam_policy.kinesis_analytics_policy.arn
  role       = aws_iam_role.kinesis_analytics_role.name
}

resource "aws_kinesis_stream" "input_stream" {
  name        = "input-stream"
  shard_count = 1
}

resource "aws_kinesis_analytics_application" "flink_app" {
  name = "flink-app"

  inputs {
    name_prefix = "SOURCE_SQL_STREAM_001"

    kinesis_streams_input {
      resource_arn = aws_kinesis_stream.input_stream.arn
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    parallelism {
      count = 1
    }

    schema {
      record_format {
        record_format_type = "JSON"

        mapping_parameters {
          json_mapping_parameters {
            record_row_path = "$"
          }
        }
      }
    }
  }

  outputs {
    name = "DESTINATION_SQL_STREAM_001"

    kinesis_firehose_output {
      resource_arn = "arn:aws:firehose:us-west-2:123456789012:deliverystream/my-delivery-stream"
      role_arn     = aws_iam_role.kinesis_analytics_role.arn
    }

    schema {
      record_format_type = "JSON"
    }
  }

  code = <<EOF
  // Example Flink code snippet
  // This is a placeholder for your actual Flink application code
  EOF

  start_application = true
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `kinesis-analytics-role` is created with a trust relationship to allow Kinesis Analytics to assume the role.
- **IAM Policy**: An IAM policy named `kinesis-analytics-policy` is created with permissions necessary for Kinesis Analytics to read from Kinesis streams and write logs to CloudWatch.
- **IAM Role Policy Attachment**: The policy is attached to the role.
- **Kinesis Stream**: A Kinesis stream named `input-stream` is created with a single shard.
- **Kinesis Analytics Application**: An Apache Flink application named `flink-app` is created, configured to read from the Kinesis stream and write output to a Firehose delivery stream. The `code` block is a placeholder for the actual Flink application code.

This configuration ensures that all dependencies are correctly handled and that the resources are properly defined and linked.

