Below is the complete Terraform HCL program that creates a Kinesis Firehose Delivery Stream with an extended S3 Destination and Dynamic Partitioning enabled. The program includes the necessary IAM roles, policies, and S3 bucket.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose_delivery_stream_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name = "firehose_delivery_stream_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Effect   = "Allow"
        Resource = [
          "arn:aws:s3:::firehose-destination-bucket-*",
          "arn:aws:s3:::firehose-destination-bucket-*/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_delivery_stream_policy" {
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

resource "aws_s3_bucket" "firehose_destination_bucket" {
  bucket = "firehose-destination-bucket-${random_string.bucket_suffix.result}"
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}

resource "aws_kinesis_firehose_delivery_stream" "extended_s3_delivery_stream" {
