Below is the complete Terraform HCL program that creates an IAM role, an IAM policy, attaches the policy to the role, and then sets up a Kinesis Firehose Delivery Stream with an HTTP endpoint destination (e.g., New Relic).

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "firehose_delivery_stream_role" {
  name = "firehose-delivery-stream-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "firehose_delivery_stream_policy" {
  name = "firehose-delivery-stream-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "http:Post"
        ]
        Effect = "Allow"
        Resource = "https://*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_firehose_delivery_stream_policy" {
  policy_arn = aws_iam_policy.firehose_delivery_stream_policy.arn
  role       = aws_iam_role.firehose_delivery_stream_role.name
}

resource "aws_kinesis_firehose_delivery_stream" "http_endpoint_delivery_stream" {
  name        = "http-endpoint-delivery-stream"
  destination = "http_endpoint"

  http_endpoint_configuration {
    url      = "https://endpoint.newrelic.com/v1/accounts/1234567/events"
    role_arn = aws_iam_role.firehose_delivery_stream_role.arn
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `firehose-delivery-stream-role` is created with a trust relationship allowing the Firehose service to assume the role.
3. **IAM Policy**: An IAM policy named `firehose-delivery-stream-policy` is created with permissions to write logs to CloudWatch Logs and to post data to any HTTP endpoint.
4. **IAM Role Policy Attachment**: The policy is attached to the role.
5. **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream named `http-endpoint-delivery-stream` is created with an HTTP endpoint destination pointing to a synthetic New Relic endpoint URL (`https://endpoint.newrelic.com/v1/accounts/1234567/events`). This URL should be replaced with the actual endpoint URL you intend to use.

This configuration ensures that the Firehose delivery stream has the necessary permissions to send data to the specified HTTP endpoint.

