```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_role" {
  name = "kendra-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kendra_policy" {
  name        = "kendra-policy"
  description = "Policy for Kendra to access necessary resources"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "kendra_policy_attachment" {
  policy_arn = aws_iam_policy.kendra_policy.arn
  role       = aws_iam_role.kendra_role.name
}

resource "aws_kendra_index" "kendra_index" {
  name     = "example-kendra-index"
  role_arn = aws_iam_role.kendra_role.arn

  description = "Example Kendra Index"
  edition     = "DEVELOPER_EDITION"

  capacity_units {
    query_capacity_units   = 1
    storage_capacity_units = 1
  }

  document_metadata_configuration_updates {
    name = "Title"
    type = "STRING_VALUE"
  }

  timeouts {
    create = "60m"
    delete = "60m"
  }
}

resource "aws_kendra_data_source" "kendra_data_source_with_proxy" {
  index_id = aws_kendra_index.kendra_index.id
  name     = "example-kendra-data-source"
  type     = "S3"

  role_arn = aws_iam_role.kendra_role.arn

  configuration {
    s3_configuration {
      bucket_name = "example-bucket-name"

      proxy_configuration {
        host     = "proxy.example.com"
        port     = 8080
        username = "proxy-user"
        password = "proxy-password"
      }
    }
  }

  description = "Example Kendra Data Source with Proxy Configuration"

  timeouts {
    create = "60m"
    delete = "60m"
  }
}
```

