Below is the complete Terraform HCL program that creates an IAM role, IAM policy, attaches the policy to the role, creates a Kendra index, and then creates a Kendra data source with URL exclusion and inclusion patterns.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "kendra_data_source_role" {
  name = "kendra-data-source-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kendra.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kendra_data_source_policy" {
  name = "kendra-data-source-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kendra_data_source_policy" {
  policy_arn = aws_iam_policy.kendra_data_source_policy.arn
  role       = aws_iam_role.kendra_data_source_role.name
}

resource "aws_kendra_index" "kendra_index" {
  name     = "example-kendra-index"
  role_arn = aws_iam_role.kendra_data_source_role.arn

