    query_capacity_units   = 1
    storage_capacity_units = 1
  }
}

resource "aws_kendra_data_source" "kendra_data_source" {
  name     = "example-kendra-data-source"
  index_id = aws_kendra_index.kendra_index.id
  type     = "WEB_CRAWLER"

  configuration {
    web_crawler_configuration {
      urls {
        seed_url_configuration {
          seed_urls = ["https://example.com"]
        }
        url_exclusion_patterns = ["https://example.com/exclude/*"]
        url_inclusion_patterns = ["https://example.com/include/*"]
      }
    }
  }
}
```

