Below is the complete Terraform HCL program that sets up a non-alias `aws_route53_record` linked to an `aws_route53_zone` resource named `private_zone` with the name parameter set to `internal.example53.com`. It also creates an `aws_vpc` resource named `main` and associates the private DNS zone with this VPC.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_route53_zone" "private_zone" {
  name = "internal.example53.com"

  vpc {
    vpc_id     = aws_vpc.main.id
    vpc_region = "us-west-2"
  }

  tags = {
    Name = "private-zone"
  }
}

resource "aws_route53_record" "non_alias_record" {
  zone_id = aws_route53_zone.private_zone.zone_id
  name    = "example.internal.example53.com"
