```hcl
# Provider configuration for AWS
provider "aws" {
  region = "us-west-2"
}

# Data source to retrieve the current caller identity
data "aws_caller_identity" "current" {}

# Data source to fetch the latest stable ECR image tagged as 'stable'
data "aws_ecr_repository" "example" {
  name = "example-repository"
}

data "aws_ecr_image" "latest_stable" {
  repository_name = data.aws_ecr_repository.example.name
  image_tag       = "stable"
}

# Local variables
locals {
  image_tag      = data.aws_ecr_image.latest_stable.image_tag
  aws_tags       = {
    Name        = "example-eks-cluster"
    Environment = "production"
  }
  workspace_name = terraform.workspace
}

# Module to instantiate an EKS cluster
module "eks_cluster" {
  source  = "terraform-aws-modules/eks/aws"
  version = "~> 18.0"

  cluster_name    = "example-eks-cluster"
  cluster_version = "1.24"

  vpc_id     = "vpc-0123456789abcdef0"
  subnets    = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
  node_groups = [
    {
      name                   = "ng-1"
      instance_type          = "t3.medium"
      min_size               = 2
      max_size               = 4
      desired_capacity       = 3
      iam_role_additional_policies = [
        "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy",
        "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy",
        "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
      ]
    }
  ]

  tags = local.aws_tags
}

# Data source to retrieve information about the created EKS cluster
data "aws_eks_cluster" "info" {
  name = module.eks_cluster.cluster_id
}

# Data source to retrieve authentication data for the created EKS cluster
data "aws_eks_cluster_auth" "auth" {
  name = module.eks_cluster.cluster_id
}

# Provider configuration for Helm
provider "helm" {
  kubernetes {
    host                   = data.aws_eks_cluster.info.endpoint
    token                  = data.aws_eks_cluster_auth.auth.token
    cluster_ca_certificate = base64decode(data.aws_eks_cluster.info.certificate_authority[0].data)
  }
}

# Provider configuration for Kubernetes
provider "kubernetes" {
  host                   = data.aws_eks_cluster.info.endpoint
  token                  = data.aws_eks_cluster_auth.auth.token
  cluster_ca_certificate = base64decode(data.aws_eks_cluster.info.certificate_authority[0].data)
}
```

