  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_worker_node_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  role       = aws_iam_role.eks_cluster_role.name
}

resource "aws_iam_role_policy_attachment" "eks_cni_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  role       = aws_iam_role.eks_cluster_role.name
}

# Create the EKS cluster
resource "aws_eks_cluster" "example_eks_cluster" {
  name     = "example"
  role_arn = aws_iam_role.eks_cluster_role.arn

  vpc_config {
    subnet_ids = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_worker_node_policy,
    aws_iam_role_policy_attachment.eks_cni_policy
  ]
}

# Create the OIDC provider for the EKS cluster
resource "aws_iam_openid_connect_provider" "oidc_provider" {
  client_id_list = ["sts.amazonaws.com"]
  url            = aws_eks_cluster.example_eks_cluster.identity[0].oidc.issuer

  thumbprint_list = [data.aws_eks_cluster_auth.example_eks_cluster.idp[0].thumbprint]

  depends_on = [aws_eks_cluster.example_eks_cluster]
}

# Data source to get the EKS cluster auth details
data "aws_eks_cluster_auth" "example_eks_cluster" {
  name = aws_eks_cluster.example_eks_cluster.name
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role for EKS Cluster**: An IAM role named `eks-cluster-role` is created with policies attached that allow the EKS cluster to function properly.
3. **EKS Cluster**: The EKS cluster named `example` is created with a specified IAM role ARN and VPC subnets.
4. **OIDC Provider**: The OIDC provider is created using the EKS cluster's OIDC issuer URL and a client ID list containing `sts.amazonaws.com`.
5. **Data Source**: A data source is used to fetch the EKS cluster's authentication details, which includes the OIDC issuer URL and thumbprint.

This configuration ensures that the OIDC provider is correctly set up and linked to the EKS cluster.

