Below is the complete Terraform HCL program that creates an AWS EKS node group named "example" linked to an EKS cluster also named "example". The program includes the necessary IAM role and policy attachments to ensure proper permissions management.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired region
}

resource "aws_iam_role" "eks_node_group_role" {
  name = "eks-node-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "eks_worker_node_policy_attachment" {
  name       = "eks-worker-node-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSWorkerNodePolicy"
  roles      = [aws_iam_role.eks_node_group_role.name]
}

resource "aws_iam_policy_attachment" "eks_cni_policy_attachment" {
  name       = "eks-cni-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKS_CNI_Policy"
  roles      = [aws_iam_role.eks_node_group_role.name]
}

resource "aws_iam_policy_attachment" "ec2_container_registry_read_only_policy_attachment" {
  name       = "ec2-container-registry-read-only-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonEC2ContainerRegistryReadOnly"
  roles      = [aws_iam_role.eks_node_group_role.name]
}

resource "aws_eks_node_group" "example_node_group" {
  cluster_name    = "example"
  node_group_name = "example"
  node_role_arn   = aws_iam_role.eks_node_group_role.arn
  subnet_ids      = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"]  # Replace with your subnet IDs

  scaling_config {
    desired_size = 1
    max_size     = 2
    min_size     = 1
  }

  update_config {
    max_unavailable = 1
  }
}
```

### Notes:
- **Region**: The region is set to `us-west-2`. You can change this to any other region where your EKS cluster is located.
- **Subnet IDs**: Replace `"subnet-0123456789abcdef0"` and `"subnet-0fedcba9876543210"` with the actual subnet IDs where you want to deploy the EKS node group.
- **Dependencies**: The `aws_eks_node_group` resource depends on the IAM policy attachments, ensuring that the necessary permissions are in place before the node group is created.
- **IAM Role**: The IAM role for the EKS node group is created with the necessary trust relationship to allow EC2 instances to assume the role. The required policies are attached to this role.

