Below is the complete Terraform HCL program that sets up an AWS IAM role (`demo_eks`) for an Amazon EKS cluster and creates the EKS cluster (`demo_eks`) with specified VPC configurations. The configuration ensures proper dependency handling for IAM role permissions during cluster management.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "demo_eks" {
  name = "demo_eks"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "eks.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "eks_cluster_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSClusterPolicy"
  role       = aws_iam_role.demo_eks.name
}

resource "aws_iam_role_policy_attachment" "eks_vpc_resource_controller_policy" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonEKSVPCResourceController"
  role       = aws_iam_role.demo_eks.name
}

resource "aws_vpc" "demo_eks" {
  cidr_block = "10.0.0.0/16"

  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "demo-eks-vpc"
  }
}

resource "aws_internet_gateway" "demo_eks" {
  vpc_id = aws_vpc.demo_eks.id

  tags = {
    Name = "demo-eks-igw"
  }
}

resource "aws_subnet" "demo_eks" {
  count                   = 3
  vpc_id                  = aws_vpc.demo_eks.id
  cidr_block              = cidrsubnet(aws_vpc.demo_eks.cidr_block, 8, count.index)
  map_public_ip_on_launch = true
  availability_zone       = element(data.aws_availability_zones.available.names, count.index)

  tags = {
    Name = "demo-eks-subnet-${count.index}"
  }
}

resource "aws_route_table" "demo_eks" {
  vpc_id = aws_vpc.demo_eks.id

  route {
    cidr_block = "0.0.0.0/0"
    gateway_id = aws_internet_gateway.demo_eks.id
  }

  tags = {
    Name = "demo-eks-route-table"
  }
}

resource "aws_route_table_association" "demo_eks" {
  count          = length(aws_subnet.demo_eks)
  subnet_id      = element(aws_subnet.demo_eks.*.id, count.index)
  route_table_id = aws_route_table.demo_eks.id
}

data "aws_availability_zones" "available" {}

resource "aws_eks_cluster" "demo_eks" {
  name     = "demo-eks"
  role_arn = aws_iam_role.demo_eks.arn

  vpc_config {
    subnet_ids = aws_subnet.demo_eks[*].id
  }

  depends_on = [
    aws_iam_role_policy_attachment.eks_cluster_policy,
    aws_iam_role_policy_attachment.eks_vpc_resource_controller_policy
  ]

  tags = {
    Name = "demo-eks-cluster"
  }
}
```

This Terraform configuration includes:
- An IAM role (`demo_eks`) with policies for EKS cluster management.
- A VPC with subnets, internet gateway, and route table associations.
- An EKS cluster (`demo_eks`) that depends on the IAM role and VPC configurations.

