    Id      = "DenySpecificIP"
    Statement = [
      {
        Sid       = "DenyAccessFromSpecificIP"
        Effect    = "Deny"
        Principal = "*"
        Action    = "s3:*"
        Resource  = [
          "${aws_s3_bucket.my_bucket.arn}",
          "${aws_s3_bucket.my_bucket.arn}/*"
        ]
        Condition = {
          IpAddress = {
            "aws:SourceIp" = "192.168.1.1/32"
          }
        }
      }
    ]
  })
}
```

