  rule {
    object_ownership = "ObjectWriter"
  }
}

resource "aws_s3_bucket" "web_data_bucket" {
  bucket = "web-data-${var.bucket_suffix}"
  acl    = "public-read"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

