  required_providers {
    aws = {
      source  = "hashicorp/aws"
      version = "~> 5.75"
    }
  }

  required_version = "~> 1.9.8"
}

provider "aws" {
  region = "us-east-1"
  profile = "admin-1"

  assume_role {
    role_arn = "arn:aws:iam::590184057477:role/yicun-iac"
  }
}

data "aws_ami" "latest_amazon_linux_2" {
  most_recent = true

  owners = ["amazon"]

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  filter {
    name   = "root-device-type"
    values = ["ebs"]
  }
}

# Create a Virtual Private Cloud (VPC)
resource "aws_vpc" "my_vpc" {
  cidr_block = "10.0.0.0/16"
}

data "aws_availability_zones" "azs" {
    state = "available"
}

resource "aws_subnet" "subnet_a" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.1.0/24"
  availability_zone = data.aws_availability_zones.azs.names[0]
}

resource "aws_subnet" "subnet_b" {
  vpc_id            = aws_vpc.my_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = data.aws_availability_zones.azs.names[1]
}

# Create an EC2 instance in Subnet A
resource "aws_instance" "ec2_instance_a" {
  ami           = data.aws_ami.latest_amazon_linux_2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_a.id

  root_block_device {
    volume_size = 50
  }
}

# # Create an EC2 instance in Subnet B
resource "aws_instance" "ec2_instance_b" {
  ami           = data.aws_ami.latest_amazon_linux_2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_b.id

  root_block_device {
    volume_size = 50
  }
}

LLM Output #0:
Below is the complete Terraform HCL program that creates a custom VPC with a CIDR block of `10.0.0.0/16`, two subnets in `us-east-1a` and `us-east-1b`, and an EC2 instance in each subnet using the latest Amazon Linux 2 AMI with a `t2.micro` instance type and an attached EBS volume of 50 GB.

```hcl
provider "aws" {
  region = "us-east-1"
}

# Fetch the latest Amazon Linux 2 AMI
data "aws_ami" "amazon_linux_2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  owners = ["amazon"]
}

# Create a custom VPC
resource "aws_vpc" "custom_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "CustomVPC"
  }
}

# Create a subnet in us-east-1a
resource "aws_subnet" "subnet_us_east_1a" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-east-1a"
  map_public_ip_on_launch = true

  tags = {
    Name = "SubnetUSEast1A"
  }
}

# Create a subnet in us-east-1b
resource "aws_subnet" "subnet_us_east_1b" {
  vpc_id                  = aws_vpc.custom_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = true

  tags = {
    Name = "SubnetUSEast1B"
  }
}

# Create an EC2 instance in us-east-1a
resource "aws_instance" "instance_in_us_east_1a" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_us_east_1a.id

  tags = {
    Name = "InstanceUSEast1A"
  }
}

# Create an EC2 instance in us-east-1b
resource "aws_instance" "instance_in_us_east_1b" {
  ami           = data.aws_ami.amazon_linux_2.id
  instance_type = "t2.micro"
  subnet_id     = aws_subnet.subnet_us_east_1b.id

  tags = {
    Name = "InstanceUSEast1B"
  }
}

# Create an EBS volume of 50 GB for the instance in us-east-1a
resource "aws_ebs_volume" "volume_for_instance_us_east_1a" {
  availability_zone = aws_instance.instance_in_us_east_1a.availability_zone
  size              = 50

  tags = {
    Name = "VolumeForInstanceUSEast1A"
  }
}

# Create an EBS volume of 50 GB for the instance in us-east-1b
resource "aws_ebs_volume" "volume_for_instance_us_east_1b" {
  availability_zone = aws_instance.instance_in_us_east_1b.availability_zone
  size              = 50

  tags = {
    Name = "VolumeForInstanceUSEast1B"
  }
}

# Attach the EBS volume to the instance in us-east-1a
resource "aws_volume_attachment" "attach_volume_to_instance_us_east_1a" {
  device_name = "/dev/sdh"
  volume_id   = aws_ebs_volume.volume_for_instance_us_east_1a.id
  instance_id = aws_instance.instance_in_us_east_1a.id
}

# Attach the EBS volume to the instance in us-east-1b
resource "aws_volume_attachment" "attach_volume_to_instance_us_east_1b" {
  device_name = "/dev/sdh"
  volume_id   = aws_ebs_volume.volume_for_instance_us_east_1b.id
  instance_id = aws_instance.instance_in_us_east_1b.id
}
```

This Terraform configuration ensures that all dependencies are correctly managed and that the infrastructure is deployed as specified in the prompt. The `aws_ami` data source fetches the latest Amazon Linux 2 AMI, and the rest of the resources are created in the correct order with appropriate dependencies.

