```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "redis_instance_role" {
  name = "redis-instance-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redis_instance_policy" {
  name = "redis-instance-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_redis_policy_to_role" {
  policy_arn = aws_iam_policy.redis_instance_policy.arn
  role       = aws_iam_role.redis_instance_role.name
}

resource "aws_vpc" "redis_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "redis_subnet" {
  vpc_id                  = aws_vpc.redis_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
}

resource "aws_security_group" "redis_security_group" {
  vpc_id = aws_vpc.redis_vpc.id
  name   = "redis-security-group"

  ingress {
    from_port   = 6379
    to_port     = 6379
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_elasticache_cluster" "redis_cluster" {
  cluster_id           = "redis-cluster"
  engine               = "redis"
  engine_version       = "6.x"
  node_type            = "cache.t3.micro"
  num_cache_nodes      = 1
  subnet_ids           = [aws_subnet.redis_subnet.id]
  security_group_ids   = [aws_security_group.redis_security_group.id]
  parameter_group_name = "default.redis6.x"
}
```

This Terraform configuration creates a VPC, a subnet within that VPC, a security group to control access to the Redis instance, an IAM role and policy for the Redis instance, and finally, the Redis cluster itself. The Redis instance is configured to use the smallest available node type (`cache.t3.micro`) and is placed in a private subnet. The security group allows inbound traffic on port 6379 from within the VPC and outbound traffic to anywhere.

