```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_policy" "redshift_policy" {
  name        = "redshift-s3-access-policy"
  description = "Policy to allow RedShift to access S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Resource = [
          "arn:aws:s3:::your-bucket-name",
          "arn:aws:s3:::your-bucket-name/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "redshift_role" {
  name               = "redshift-s3-access-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [aws_iam_policy.redshift_policy.arn]
}

resource "aws_redshift_cluster" "redshift_cluster_single_node" {
  cluster_identifier                  = "single-node-redshift-cluster"
  node_type                           = "dc2.large"
  master_username                     = "adminuser"
  master_password                     = "yourStrong!Passw0rd"
  iam_roles                           = [aws_iam_role.redshift_role.arn]
  cluster_subnet_group_name           = "default" # Ensure this subnet group exists or create it
  publicly_accessible                 = false
  skip_final_cluster_snapshot         = true
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Policy**: An IAM policy named `redshift-s3-access-policy` is created to allow RedShift to access S3 buckets. Replace `"your-bucket-name"` with your actual S3 bucket name.
3. **IAM Role**: An IAM role named `redshift-s3-access-role` is created with the trust relationship to be assumed by RedShift. This role is attached with the previously created policy.
4. **RedShift Cluster**: A RedShift cluster named `single-node-redshift-cluster` is created with a single node (`dc2.large`). The cluster is configured with a master username and password, and the IAM role is associated for S3 access. The cluster is not publicly accessible, and final snapshots are skipped during deletion.

Make sure to replace placeholders like `"your-bucket-name"` and `"yourStrong!Passw0rd"` with actual values before deploying. Also, ensure that the `cluster_subnet_group_name` refers to an existing subnet group or create one as needed.

