```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-cluster-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "redshift_policy_attachment" {
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  role       = aws_iam_role.redshift_role.name
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier = "my-redshift-cluster"
  node_type          = "dc2.large"
  master_username    = "admin"
  master_password    = "securepassword123"
  cluster_type       = "multi-node"
  number_of_nodes    = 2
  iam_roles          = [aws_iam_role.redshift_role.arn]
}

resource "aws_redshift_snapshot_schedule" "snapshot_schedule" {
  identifier = "my-snapshot-schedule"
  definitions = ["cron(0 12 * * ? *)"] # Daily at 12 PM UTC
}

resource "aws_redshift_snapshot_schedule_association" "snapshot_schedule_association" {
  cluster_identifier = aws_redshift_cluster.redshift_cluster.cluster_identifier
  schedule_identifier  = aws_redshift_snapshot_schedule.snapshot_schedule.identifier
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `redshift-cluster-role` is created with a trust relationship allowing RedShift to assume the role.
3. **IAM Policy Attachment**: The `AmazonS3ReadOnlyAccess` policy is attached to the IAM role to allow RedShift to read from S3 buckets.
4. **RedShift Cluster**: A RedShift cluster named `my-redshift-cluster` is created with two nodes (`dc2.large` type), a master username, and password. The cluster uses the IAM role created earlier.
5. **Snapshot Schedule**: A snapshot schedule named `my-snapshot-schedule` is defined to take snapshots daily at 12 PM UTC.
6. **Snapshot Schedule Association**: The snapshot schedule is associated with the RedShift cluster.

This configuration ensures that the RedShift cluster is set up with the necessary IAM permissions and has a snapshot schedule to manage concurrency scaling effectively.

