```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "redshift_snapshot_role" {
  name = "redshift-snapshot-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "redshift_snapshot_policy" {
  name = "redshift-snapshot-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:Describe*",
          "ec2:CreateSnapshot",
          "ec2:DeleteSnapshot"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_redshift_snapshot_policy" {
  policy_arn = aws_iam_policy.redshift_snapshot_policy.arn
  role       = aws_iam_role.redshift_snapshot_role.name
}

resource "aws_redshift_snapshot_schedule" "snapshot_schedule" {
  identifier = "redshift-snapshot-schedule"
  definitions = ["cron(0 0/12 * * ? *)"] # Every 12 hours
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier                  = "single-node-redshift-cluster"
  node_type                           = "dc2.large"
  master_username                     = "adminuser"
  master_password                     = "securepassword123"
  iam_roles                           = [aws_iam_role.redshift_snapshot_role.arn]
  automated_snapshot_retention_period = 30
}

resource "aws_redshift_snapshot_schedule_association" "associate_snapshot_schedule" {
  cluster_identifier  = aws_redshift_cluster.redshift_cluster.cluster_identifier
  schedule_identifier = aws_redshift_snapshot_schedule.snapshot_schedule.identifier
}
```

