  map_public_ip_on_launch = true

  tags = {
    Name = "redshift-subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-east-1b"
  map_public_ip_on_launch = true

  tags = {
    Name = "redshift-subnet-b"
  }
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "redshift-subnet-group"
  }
}

resource "aws_iam_role" "redshift_role" {
  name = "redshift-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "redshift-role"
  }
}

resource "aws_iam_policy_attachment" "redshift_policy_attachment" {
  name       = "redshift-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/AmazonS3ReadOnlyAccess"
  roles      = [aws_iam_role.redshift_role.name]
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier            = "redshift-cluster"
  node_type                     = "dc2.large"
  master_username               = "admin"
  master_password               = "Password123!"
  cluster_subnet_group_name     = aws_redshift_subnet_group.redshift_subnet_group.name
  iam_roles                     = [aws_iam_role.redshift_role.arn]
  publicly_accessible           = false
  enhanced_vpc_routing          = true
  automated_snapshot_retention_period = 7

  logging {
    enable         = true
    bucket_name    = "redshift-logs-bucket"
    s3_key_prefix  = "cluster-logs/"
  }

  tags = {
    Name = "redshift-cluster"
  }
}
```

