Below is the complete Terraform HCL program that sets up a 2-node RedShift cluster in `us-east-1` and replicates it to `us-east-2`. The program includes the necessary IAM role and policy for replication.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_iam_policy" "redshift_replication_policy" {
  name        = "RedshiftReplicationPolicy"
  description = "IAM policy for RedShift replication"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "redshift:DescribeClusters",
          "redshift:CreateClusterSnapshot",
          "redshift:DeleteClusterSnapshot",
          "redshift:CopyClusterSnapshot",
          "redshift:AuthorizeSnapshotAccess",
          "redshift:RestoreFromClusterSnapshot"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "redshift_replication_role" {
  name = "RedshiftReplicationRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "redshift.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_redshift_replication_policy" {
  policy_arn = aws_iam_policy.redshift_replication_policy.arn
  role       = aws_iam_role.redshift_replication_role.name
}

resource "aws_redshift_cluster" "redshift_cluster_us_east_1" {
  cluster_identifier                  = "redshift-cluster-us-east-1"
  node_type                           = "dc2.large"
  master_username                     = "admin"
  master_password                     = "securepassword123"
  cluster_type                        = "multi-node"
  number_of_nodes                     = 2
  iam_roles                           = [aws_iam_role.redshift_replication_role.arn]
  skip_final_cluster_snapshot         = true
  enhanced_vpc_routing                = true
  automated_snapshot_retention_period = 7
}

resource "aws_redshift_cluster" "redshift_cluster_us_east_2" {
  provider                            = aws.us_east_2
  cluster_identifier                  = "redshift-cluster-us-east-2"
  node_type                           = "dc2.large"
  master_username                     = "admin"
  master_password                     = "securepassword123"
  cluster_type                        = "single-node"
  iam_roles                           = [aws_iam_role.redshift_replication_role.arn]
  skip_final_cluster_snapshot         = true
  enhanced_vpc_routing                = true
  automated_snapshot_retention_period = 7

  snapshot_copy {
    destination_region = "us-east-2"
    retention_period   = 7
  }

  depends_on = [aws_redshift_cluster.redshift_cluster_us_east_1]
}

provider "aws" "us_east_2" {
  region = "us-east-2"
}
```

### Explanation:
1. **Provider Configuration**: Configured for `us-east-1` initially, and a secondary provider for `us-east-2` is defined.
2. **IAM Policy and Role**: Created an IAM policy and role with necessary permissions for RedShift replication.
3. **RedShift Cluster in `us-east-1`**: A multi-node RedShift cluster is created in `us-east-1`.
4. **RedShift Cluster in `us-east-2`**: A single-node RedShift cluster is created in `us-east-2` and configured to replicate snapshots from the `us-east-1` cluster using the `snapshot_copy` block.
5. **Dependencies**: The `us-east-2` cluster depends on the `us-east-1` cluster to ensure it is created after the primary cluster.

This configuration ensures that the RedShift clusters are set up correctly and that the replication is configured between the two regions.

