Below is the complete Terraform HCL program that creates a Lambda function and invokes it every 15 minutes using AWS resources. The program includes the necessary IAM role, policy attachment, Lambda function, CloudWatch event rule, and event target.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "attach_lambda_basic_execution_policy" {
  name       = "attach-lambda-basic-execution-policy"
  roles      = [aws_iam_role.lambda_execution_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
}

resource "aws_lambda_function" "scheduled_lambda_function" {
  function_name = "scheduled-lambda-function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"

  filename         = "${path.module}/lambda_function_payload.zip"
  source_code_hash = filebase64sha256("${path.module}/lambda_function_payload.zip")

  environment {
    variables = {
      ENVIRONMENT = "production"
    }
  }
}

resource "aws_cloudwatch_event_rule" "invoke_lambda_every_15_minutes" {
  name                = "invoke-lambda-every-15-minutes"
  schedule_expression = "rate(15 minutes)"
}

resource "aws_cloudwatch_event_target" "target_scheduled_lambda_function" {
  arn  = aws_lambda_function.scheduled_lambda_function.arn
  rule = aws_cloudwatch_event_rule.invoke_lambda_every_15_minutes.name
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Role**: An IAM role named `lambda-execution-role` is created with a trust relationship allowing Lambda to assume the role.
3. **IAM Policy Attachment**: The `AWSLambdaBasicExecutionRole` policy is attached to the Lambda execution role.
4. **Lambda Function**: A Lambda function named `scheduled-lambda-function` is created. It uses Python 3.8 as the runtime and expects a deployment package (`lambda_function_payload.zip`) in the same directory as the Terraform configuration.
5. **CloudWatch Event Rule**: A CloudWatch event rule named `invoke-lambda-every-15-minutes` is created with a schedule expression to trigger every 15 minutes.
6. **CloudWatch Event Target**: The event target is configured to invoke the Lambda function whenever the event rule is triggered.

Make sure to have a valid `lambda_function_payload.zip` file in the same directory as your Terraform configuration, or adjust the `filename` attribute accordingly.

