```hcl
provider "aws" {
  region = var.region
}

variable "region" {
  type    = string
  default = "us-east-1"
}

variable "table_name" {
  type    = string
  default = "MyDynamoDBTable"
}

resource "aws_dynamodb_table" "dynamodb_table_us_east_1" {
  provider = aws.us_east_1

  name           = "${var.table_name}-us-east-1"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name        = "${var.table_name}-us-east-1"
    Environment = "production"
  }
}

resource "aws_dynamodb_table" "dynamodb_table_us_west_1" {
  provider = aws.us_west_1

  name           = "${var.table_name}-us-west-1"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
    name = "id"
    type = "S"
  }

  tags = {
    Name        = "${var.table_name}-us-west-1"
    Environment = "production"
  }
}

resource "aws_dynamodb_table" "dynamodb_table_us_west_2" {
  provider = aws.us_west_2

  name           = "${var.table_name}-us-west-2"
  billing_mode   = "PAY_PER_REQUEST"
  hash_key       = "id"

  attribute {
