Below is a complete Terraform HCL program that sets up a Kinesis stream, a Lambda function, and necessary IAM roles and policies to enable streaming data from Kinesis to a DynamoDB table. This configuration adheres to the requirements and dependencies outlined in your prompt.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_dynamodb_table" "dynamodb_table" {
  name           = "example-dynamodb-table"
  billing_mode   = "PAY_PER_REQUEST"
  stream_enabled = true
  stream_view_type = "NEW_AND_OLD_IMAGES"

  attribute {
    name = "id"
    type = "S"
  }

  hash_key = "id"
}

resource "aws_iam_role" "kinesis_streaming_role" {
  name = "kinesis-streaming-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "kinesis_streaming_policy" {
  name = "kinesis-streaming-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:UpdateItem",
          "dynamodb:DeleteItem"
        ]
        Effect = "Allow"
        Resource = aws_dynamodb_table.dynamodb_table.arn
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_kinesis_streaming_policy" {
  policy_arn = aws_iam_policy.kinesis_streaming_policy.arn
  role       = aws_iam_role.kinesis_streaming_role.name
}

resource "aws_kinesis_stream" "kinesis_stream" {
  name        = "example-kinesis-stream"
  shard_count = 1
}

resource "aws_lambda_function" "lambda_function" {
  function_name = "example-lambda-function"
  role          = aws_iam_role.kinesis_streaming_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"

  environment {
    variables = {
      DYNAMODB_TABLE_NAME = aws_dynamodb_table.dynamodb_table.name
    }
  }
}

resource "aws_lambda_permission" "allow_kinesis_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromKinesis"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.lambda_function.function_name
  principal     = "kinesis.amazonaws.com"
  source_arn    = aws_kinesis_stream.kinesis_stream.arn
}

resource "aws_kinesis_event_source_mapping" "kinesis_event_source_mapping" {
  function_name = aws_lambda_function.lambda_function.function_name
  batch_size    = 100
  starting_position = "LATEST"
  stream_arn    = aws_kinesis_stream.kinesis_stream.arn
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **DynamoDB Table**: A DynamoDB table named `example-dynamodb-table` is created with a stream enabled.
- **IAM Role and Policy**: An IAM role (`kinesis-streaming-role`) and policy (`kinesis-streaming-policy`) are created to allow the Lambda function to write to the DynamoDB table and log to CloudWatch Logs.
- **Kinesis Stream**: A Kinesis stream named `example-kinesis-stream` is created with a single shard.
- **Lambda Function**: A Lambda function named `example-lambda-function` is created, which processes records from the Kinesis stream and writes them to the DynamoDB table.
- **Permissions and Event Source Mapping**: Permissions are granted to Kinesis to invoke the Lambda function, and an event source mapping is created to trigger the Lambda function on new records in the Kinesis stream.

