```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "sagemaker_pipeline_role" {
  name = "sagemaker-pipeline-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "sagemaker.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "sagemaker_pipeline_policy" {
  name = "sagemaker-pipeline-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "sagemaker:*",
          "ecr:GetDownloadUrlForLayer",
          "ecr:BatchGetImage",
          "ecr:DescribeRepositories",
          "ecr:ListImages",
          "ecr:DescribeImages",
          "ecr:GetRepositoryPolicy",
          "ecr:GetAuthorizationToken",
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "s3:GetObject",
          "s3:PutObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_sagemaker_pipeline_policy" {
  policy_arn = aws_iam_policy.sagemaker_pipeline_policy.arn
  role       = aws_iam_role.sagemaker_pipeline_role.name
}

resource "aws_sagemaker_pipeline" "sagemaker_pipeline" {
  pipeline_display_name = "MySageMakerPipeline"
  pipeline_name         = "my-sagemaker-pipeline"
  role_arn              = aws_iam_role.sagemaker_pipeline_role.arn

  pipeline_definition = jsonencode({
    Version = "2020-12-01"
    Steps = [
      {
        Name = "ExampleStep"
        Type = "Training"
        Arguments = {
          AlgorithmSpecification = {
            TrainingImage = "123456789012.dkr.ecr.us-west-2.amazonaws.com/my-training-image:latest"
            TrainingInputMode = "File"
          }
          InputDataConfig = [
            {
              ChannelName = "train"
              DataSource = {
                S3DataSource = {
                  S3DataType = "S3Prefix"
                  S3Uri = "s3://my-bucket/train/"
                }
              }
            }
          ]
          OutputDataConfig = {
            S3OutputPath = "s3://my-bucket/output/"
          }
          ResourceConfig = {
            InstanceCount = 1
            InstanceType = "ml.m5.large"
            VolumeSizeInGB = 30
          }
          RoleArn = aws_iam_role.sagemaker_pipeline_role.arn
          StoppingCondition = {
            MaxRuntimeInSeconds = 3600
          }
        }
      }
    ]
  })
}
```

This Terraform configuration sets up the necessary IAM role and policy for executing a SageMaker Pipeline and defines a simple pipeline with a training step. The pipeline definition is provided as a JSON string within the `pipeline_definition` attribute. Adjust the `AlgorithmSpecification`, `InputDataConfig`, and other parameters as needed for your specific use case.

