```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true
  availability_zone       = "us-west-2a"
  tags = {
    Name = "PublicSubnet"
  }
}

resource "aws_subnet" "private_subnet" {
  vpc_id            = aws_vpc.main_vpc.id
  cidr_block        = "10.0.2.0/24"
  availability_zone = "us-west-2b"
  tags = {
    Name = "PrivateSubnet"
  }
}

resource "aws_iam_role" "ec2_fleet_role" {
  name = "EC2FleetRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "ec2fleet.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "EC2FleetRole"
  }
}

resource "aws_iam_policy_attachment" "attach_ec2_fleet_policy" {
  name       = "AttachEC2FleetPolicy"
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonEC2FleetCompleteAccess"
  roles      = [aws_iam_role.ec2_fleet_role.name]
}

data "aws_ami" "amazon_linux2" {
  most_recent = true

  filter {
    name   = "name"
    values = ["amzn2-ami-hvm-*-x86_64-gp2"]
  }

  owners = ["amazon"]
}

resource "aws_launch_template" "ec2_fleet_launch_template" {
  name          = "EC2FleetLaunchTemplate"
  image_id      = data.aws_ami.amazon_linux2.id
  instance_type = "t3.micro"

  iam_instance_profile {
    name = aws_iam_role.ec2_fleet_role.name
  }

  tags = {
    Name = "EC2FleetInstance"
  }
}

resource "aws_ec2_fleet" "main_ec2_fleet" {
  type = "maintain"

  launch_template_config {
    launch_template_specification {
      launch_template_id = aws_launch_template.ec2_fleet_launch_template.id
    }
  }

  target_capacity_specification {
    default_target_capacity_type = "spot"
    total_target_capacity        = 9
    on_demand_target_capacity    = 5
    spot_target_capacity         = 4
  }

  on_demand_options {
    allocation_strategy = "lowest-price"
  }

  spot_options {
    allocation_strategy = "lowest-price"
  }

  tags = {
    Name = "MainEC2Fleet"
  }
}
