```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_placement_group" "clustering_placement_group" {
  name     = "clustering-placement-group"
  strategy = "cluster"
}

resource "aws_security_group" "example_sg" {
  name        = "example-sg"
  description = "Allow SSH and HTTP traffic"

  ingress {
    from_port   = 22
    to_port     = 22
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_key_pair" "example_key_pair" {
  key_name   = "example-key-pair"
  public_key = file("~/.ssh/id_rsa.pub")
}

resource "aws_instance" "ec2_instance_1" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t3.micro"
  placement_group = aws_placement_group.clustering_placement_group.name

  vpc_security_group_ids = [aws_security_group.example_sg.id]
  key_name               = aws_key_pair.example_key_pair.key_name

  tags = {
    Name = "EC2-Instance-1"
  }
}

resource "aws_instance" "ec2_instance_2" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t3.micro"
  placement_group = aws_placement_group.clustering_placement_group.name

  vpc_security_group_ids = [aws_security_group.example_sg.id]
  key_name               = aws_key_pair.example_key_pair.key_name

  tags = {
    Name = "EC2-Instance-2"
  }
}

resource "aws_instance" "ec2_instance_3" {
  ami           = "ami-0c55b159cbfafe1f0" # Amazon Linux 2 AMI (HVM), SSD Volume Type
  instance_type = "t3.micro"
  placement_group = aws_placement_group.clustering_placement_group.name

  vpc_security_group_ids = [aws_security_group.example_sg.id]
  key_name               = aws_key_pair.example_key_pair.key_name

  tags = {
    Name = "EC2-Instance-3"
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **Placement Group**: An EC2 placement group named `clustering-placement-group` is created with the `cluster` strategy.
- **Security Group**: A security group `example-sg` is created to allow SSH (port 22) and HTTP (port 80) traffic from anywhere (`0.0.0.0/0`). It also allows all outbound traffic.
- **Key Pair**: A key pair `example-key-pair` is created using a public key from the local machine. Ensure the path to your public key is correct.
- **EC2 Instances**: Three EC2 instances (`ec2_instance_1`, `ec2_instance_2`, `ec2_instance_3`) are created using the Amazon Linux 2 AMI (`ami-0c55b159cbfafe1f0`) and `t3.micro` instance type. Each instance is placed in the `clustering-placement-group` and associated with the `example-sg` security group and `example-key-pair` key pair. Tags are added for easy identification.

