Below is the complete Terraform HCL program that sets up an IAM role, an IAM policy, attaches the policy to the role, creates an ElastiCache user for Redis, and adds the user to a user group. This configuration ensures that the ElastiCache user is authenticated using the specified IAM role.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "elasticache_user_auth_role" {
  name = "elasticache_user_auth_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "elasticache.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "elasticache_user_auth_policy" {
  name = "elasticache_user_auth_policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "elasticache:CreateUser",
          "elasticache:ModifyUser",
          "elasticache:DeleteUser",
          "elasticache:DescribeUsers",
          "elasticache:CreateUserGroup",
          "elasticache:ModifyUserGroup",
          "elasticache:DeleteUserGroup",
          "elasticache:DescribeUserGroups"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_elasticache_user_auth_policy" {
  policy_arn = aws_iam_policy.elasticache_user_auth_policy.arn
  role       = aws_iam_role.elasticache_user_auth_role.name
}

resource "aws_elasticache_user" "redis_user" {
  user_id     = "redis-user-id"
  user_name   = "redis-user"
  engine      = "redis"
  access_string = "on ~* &* +@all"

  authentication_mode {
    type = "iam"
  }
}

resource "aws_elasticache_user_group" "redis_user_group" {
  user_group_id = "redis-user-group"
  engine        = "redis"
  user_ids      = [aws_elasticache_user.redis_user.user_id]
}
```

This Terraform configuration will:
1. Define an IAM role (`elasticache_user_auth_role`) that can be assumed by ElastiCache.
2. Define an IAM policy (`elasticache_user_auth_policy`) with permissions necessary for managing ElastiCache users and user groups.
3. Attach the IAM policy to the IAM role.
4. Create an ElastiCache user (`redis_user`) for Redis with IAM authentication.
5. Add the Redis user to a user group (`redis_user_group`). 

Make sure to adjust the `region` in the provider block if you need to deploy this in a different AWS region.

