LLM Output #0:
Below is the complete Terraform HCL program that creates a managed MSK cluster in `us-east-1` and configures it to log to an S3 bucket. The program includes the necessary IAM role and policy for MSK to write logs to the S3 bucket.

```hcl
provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "msk_logging_bucket" {
  bucket = "msk-logging-bucket-unique-name"
  acl    = "private"

  tags = {
    Name = "MSK Logging Bucket"
  }
}

resource "aws_iam_policy" "msk_logging_policy" {
  name        = "msk_logging_policy"
  description = "Policy to allow MSK to write logs to S3"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:PutObject",
          "s3:GetBucketAcl",
          "s3:ListBucket"
        ]
        Resource = [
          aws_s3_bucket.msk_logging_bucket.arn,
          "${aws_s3_bucket.msk_logging_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "msk_logging_role" {
  name = "msk_logging_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "logs.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name = "MSK Logging Role"
  }
}

resource "aws_iam_role_policy_attachment" "attach_msk_logging_policy" {
  policy_arn = aws_iam_policy.msk_logging_policy.arn
  role       = aws_iam_role.msk_logging_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type  = "kafka.m5.large"
    security_groups  = ["sg-0123456789abcdef0"]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      s3 {
        enabled   = true
        bucket    = aws_s3_bucket.msk_logging_bucket.id
        prefix    = "msk-logs/"
        log_format = "JSON"
      }
    }
  }

  tags = {
    Name = "Managed MSK Cluster"
  }
}
```

### Explanation:
- **Provider Configuration**: Sets the AWS region to `us-east-1`.
- **S3 Bucket**: Creates an S3 bucket named `msk-logging-bucket-unique-name` with private ACL.
- **IAM Policy**: Defines a policy that allows MSK to write logs to the S3 bucket.
- **IAM Role**: Creates an IAM role that MSK can assume to write logs to the S3 bucket.
- **IAM Role Policy Attachment**: Attaches the logging policy to the logging role.
- **MSK Cluster**: Creates a managed MSK cluster with three broker nodes, specifying the client subnets, instance type, and security groups. It also configures logging to the S3 bucket using the defined role and policy.

Make sure to replace the `client_subnets` and `security_groups` with valid subnet IDs and security group IDs from your AWS account.

