LLM Output #0:
Certainly! Below is the complete Terraform HCL program that creates a managed MSK cluster in `us-east-1` and configures it to log to a Kinesis Firehose delivery stream. The program includes all necessary resources and their dependencies as per the provided graph.

```hcl
provider "aws" {
  region = "us-east-1"
}

# Create an S3 bucket for Kinesis Firehose to deliver logs
resource "aws_s3_bucket" "firehose_bucket" {
  bucket = "terraform-msk-firehose-logs"
}

# Create an IAM role for MSK to send logs to Kinesis Firehose
resource "aws_iam_role" "msk_firehose_role" {
  name = "msk_firehose_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
      }
    ]
  })
}

# Create an IAM policy granting MSK permissions to send logs to Kinesis Firehose
resource "aws_iam_policy" "msk_firehose_policy" {
  name        = "msk_firehose_policy"
  description = "Policy for MSK to send logs to Kinesis Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "firehose:PutRecord",
          "firehose:PutRecordBatch"
        ]
        Effect   = "Allow"
        Resource = aws_kinesis_firehose_delivery_stream.firehose_stream.arn
      }
    ]
  })
}

# Attach the MSK Firehose policy to the MSK Firehose role
resource "aws_iam_role_policy_attachment" "attach_msk_firehose_policy" {
  policy_arn = aws_iam_policy.msk_firehose_policy.arn
  role       = aws_iam_role.msk_firehose_role.name
}

# Create a Kinesis Firehose delivery stream to receive logs from MSK
resource "aws_kinesis_firehose_delivery_stream" "firehose_stream" {
  name        = "firehose_stream"
  destination = "extended_s3"

  extended_s3_configuration {
    bucket_arn = aws_s3_bucket.firehose_bucket.arn
    role_arn   = aws_iam_role.msk_firehose_role.arn
  }
}

# Create a managed MSK cluster configured to log to Kinesis Firehose
resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed_msk_cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    instance_type = "kafka.m5.large"
    client_subnets  = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"] # Replace with actual subnet IDs
    security_groups = ["sg-12345678"] # Replace with actual security group ID

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  logging_info {
    broker_logs {
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.firehose_stream.name
      }
    }
  }
}
```

### Notes:
- **S3 Bucket**: An S3 bucket named `terraform-msk-firehose-logs` is created to store the logs delivered by Kinesis Firehose.
- **IAM Role and Policy**: An IAM role (`msk_firehose_role`) and policy (`msk_firehose_policy`) are created to allow MSK to send logs to Kinesis Firehose.
- **Kinesis Firehose Delivery Stream**: A Kinesis Firehose delivery stream (`firehose_stream`) is set up to deliver logs to the S3 bucket.
- **MSK Cluster**: A managed MSK cluster (`managed_msk_cluster`) is created with three broker nodes, and it is configured to log to the Kinesis Firehose delivery stream.

Make sure to replace the placeholder subnet and security group IDs with actual values from your AWS environment.

