Below is a complete Terraform HCL program that creates a managed MSK cluster with the necessary IAM role and policy. Note that JMX Exporter and Node Exporter configurations are not directly supported by the AWS MSK resource and would require additional setup outside of this Terraform configuration, as mentioned in the notes.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "msk_execution_role" {
  name = "msk-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "msk_execution_policy" {
  name = "msk-execution-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "cloudwatch:*",
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeSubnets",
          "ec2:DescribeSecurityGroups",
          "ec2:DescribeVpcs",
          "ec2:DescribeDhcpOptions",
          "ec2:DescribeInternetGateways",
          "ec2:DescribeRouteTables",
          "ec2:DescribeNetworkInterfaces"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_execution_policy" {
  policy_arn = aws_iam_policy.msk_execution_policy.arn
  role       = aws_iam_role.msk_execution_role.name
}

resource "aws_msk_cluster" "managed_msk_cluster" {
  cluster_name           = "managed-msk-cluster"
  kafka_version          = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"]
    instance_type  = "kafka.m5.large"
    security_groups  = ["sg-12345678"]

    az_distribution = "DEFAULT"
  }

  client_authentication {
    unauthenticated {
      enabled = true
    }
  }

  tags = {
    Name = "ManagedMSKCluster"
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `msk-execution-role` is created with a trust relationship allowing the MSK service to assume the role.
- **IAM Policy**: An IAM policy named `msk-execution-policy` is created with permissions required by MSK.
- **IAM Role Policy Attachment**: The policy is attached to the role.
- **MSK Cluster**: A managed MSK cluster named `managed-msk-cluster` is created with three broker nodes using the `kafka.m5.large` instance type. It uses three example subnet IDs and a security group ID. The cluster allows unauthenticated access for demonstration purposes.

Please replace the example subnet IDs (`subnet-12345678`, `subnet-87654321`, `subnet-abcdef12`) and security group ID (`sg-12345678`) with actual values from your AWS environment.

