Certainly! Below is a complete Terraform HCL program that creates a serverless MSK cluster in the `us-east-2` region. This configuration includes the necessary IAM role and policy for the MSK cluster to operate. Note that some placeholder values are used for subnets, security groups, and KMS keys, which should be replaced with actual values from your AWS environment.

```hcl
provider "aws" {
  region = "us-east-2"
}

resource "aws_iam_policy" "msk_execution_policy" {
  name        = "msk_execution_policy"
  description = "Policy for MSK execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "msk_execution_role" {
  name = "msk_execution_role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "managedstreamprocessing.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_msk_execution_policy" {
  policy_arn = aws_iam_policy.msk_execution_policy.arn
  role       = aws_iam_role.msk_execution_role.name
}

resource "aws_msk_cluster" "serverless_msk_cluster" {
  cluster_name           = "serverless-msk-cluster"
  kafka_version          = "2.8.1"
  storage_mode           = "serverless"

  broker_node_group_info {
    client_subnets  = ["subnet-12345678", "subnet-87654321"] # Replace with actual subnet IDs
    instance_type     = "kafka.m5.large"
    security_groups   = ["sg-12345678"] # Replace with actual security group ID
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-east-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234" # Replace with actual KMS key ARN
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled   = true
        log_group = "/aws/msk/serverless-msk-cluster"
      }
    }
  }

  depends_on = [aws_iam_role_policy_attachment.attach_msk_execution_policy]
}
```

### Key Points:
- **Provider Configuration**: The AWS provider is set to the `us-east-2` region.
- **IAM Policy and Role**: An IAM policy and role are created to allow MSK to write logs to CloudWatch.
- **MSK Cluster**: A serverless MSK cluster is created with the specified Kafka version and storage mode.
- **Subnets and Security Groups**: Placeholder values are used for subnets and security groups. Replace these with actual values from your AWS environment.
- **KMS Key**: A placeholder KMS key ARN is used. Replace this with the ARN of an actual KMS key in your AWS account.

This configuration ensures that all dependencies are correctly handled and that the MSK cluster can operate with the necessary permissions.

