LLM Output #0:
Below is the complete Terraform HCL program that creates an MSK cluster with 3 broker nodes, outputs to a CloudWatch log group, an S3 bucket, and a Kinesis Firehose delivery stream. The MSK cluster is configured with encryption at rest and open monitoring.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_policy" "msk_policy" {
  name        = "msk-policy"
  description = "Policy for MSK"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "logs:CreateLogStream",
          "logs:PutLogEvents",
          "s3:PutObject",
          "s3:GetBucketLocation",
          "kinesis:PutRecord",
          "kinesis:PutRecords"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "msk_role" {
  name               = "msk-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "kafka.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [aws_iam_policy.msk_policy.arn]
}

resource "aws_iam_policy" "firehose_policy" {
  name        = "firehose-policy"
  description = "Policy for Firehose"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:AbortMultipartUpload",
          "s3:GetBucketLocation",
          "s3:GetObject",
          "s3:ListBucket",
          "s3:ListBucketMultipartUploads",
          "s3:PutObject"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "firehose_role" {
  name               = "firehose-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "firehose.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [aws_iam_policy.firehose_policy.arn]
}

resource "aws_s3_bucket" "s3_bucket" {
  bucket = "msk-logs-bucket-${random_string.bucket_suffix.result}"
}

resource "aws_kinesis_firehose_delivery_stream" "firehose_delivery_stream" {
  name        = "msk-firehose-stream"
  destination = "extended_s3"

  extended_s3_configuration {
    role_arn   = aws_iam_role.firehose_role.arn
    bucket_arn = aws_s3_bucket.s3_bucket.arn
  }
}

resource "aws_cloudwatch_log_group" "cloudwatch_log_group" {
  name = "/aws/msk/broker-logs"
}

resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "2.8.1"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets = ["subnet-12345678", "subnet-87654321", "subnet-abcdef12"]
    instance_type  = "kafka.m5.large"
    security_groups  = ["sg-12345678"]
  }

  encryption_info {
    encryption_at_rest_kms_key_arn = "arn:aws:kms:us-west-2:123456789012:key/abcd1234-abcd-1234-abcd-1234abcd1234"
  }

  logging_info {
    broker_logs {
      cloudwatch_logs {
        enabled    = true
        log_group  = aws_cloudwatch_log_group.cloudwatch_log_group.name
      }
      firehose {
        enabled         = true
        delivery_stream = aws_kinesis_firehose_delivery_stream.firehose_delivery_stream.name
      }
      s3 {
        enabled = true
        bucket  = aws_s3_bucket.s3_bucket.bucket
      }
    }
  }

  open_monitoring {
    prometheus {
      jmx_exporter {
        enabled_in_broker = true
      }
      node_exporter {
        enabled_in_broker = true
      }
    }
  }
}

resource "random_string" "bucket_suffix" {
  length  = 8
  special = false
}
```

This Terraform configuration includes:
- An IAM policy and role for MSK.
- An IAM policy and role for Kinesis Firehose.
- An S3 bucket for storing MSK logs.
- A Kinesis Firehose delivery stream.
- A CloudWatch log group for MSK broker logs.
- An MSK cluster with 3 broker nodes, encryption at rest, and open monitoring.

Make sure to replace the `client_subnets` and `security_groups` with valid subnet IDs and security group IDs from your AWS environment. The `encryption_at_rest_kms_key_arn` should also be replaced with a valid KMS key ARN if you want to use a specific key for encryption.

