Below is the complete Terraform HCL program that creates an MSK cluster with 3 broker nodes, an MSK Connect custom plugin using a "debezium.zip" file, and an MSK Connect connector that uses the custom plugin and connects to the MSK cluster.

```hcl
provider "aws" {
  region = "us-east-1"
}

# IAM Role for MSK Connect
resource "aws_iam_role" "msk_connect_role" {
  name = "msk-connect-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "kafkaconnect.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for MSK Connect
resource "aws_iam_policy" "msk_connect_policy" {
  name = "msk-connect-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:*",
          "s3:GetObject",
          "s3:ListBucket",
          "ec2:Describe*",
          "ec2:CreateNetworkInterface",
          "ec2:DeleteNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:ModifyNetworkInterfaceAttribute",
          "ec2:AssignPrivateIpAddresses",
          "ec2:UnassignPrivateIpAddresses"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

# Attach the policy to the role
resource "aws_iam_role_policy_attachment" "attach_msk_connect_policy" {
  policy_arn = aws_iam_policy.msk_connect_policy.arn
  role       = aws_iam_role.msk_connect_role.name
}

# MSK Cluster Configuration
resource "aws_msk_configuration" "msk_configuration" {
  name             = "msk-config"
  server_properties = <<EOF
auto.create.topics.enable = true
default.replication.factor = 3
EOF
}

# MSK Cluster
resource "aws_msk_cluster" "msk_cluster" {
  cluster_name           = "my-msk-cluster"
  kafka_version          = "3.4.0"
  number_of_broker_nodes = 3

  broker_node_group_info {
    client_subnets  = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
    instance_type   = "kafka.m5.large"
    security_groups = ["sg-0123456789abcdef0"]

    storage_info {
      ebs_storage_info {
        volume_size = 100
      }
    }
  }

  configuration_info {
    arn      = aws_msk_configuration.msk_configuration.arn
    revision = aws_msk_configuration.msk_configuration.latest_revision
  }
}

# MSK Connect Custom Plugin
resource "aws_mskconnect_custom_plugin" "custom_plugin" {
  name         = "debezium-plugin"
  content_type = "ZIP"

  location {
    s3 {
      bucket_arn = "arn:aws:s3:::my-bucket"
      file_key   = "debezium.zip"
    }
  }
}

# MSK Connect Connector
resource "aws_mskconnect_connector" "msk_connector" {
  name                  = "my-msk-connector"
  kafkaconnect_version  = "2.7.1"
  service_execution_role_arn = aws_iam_role.msk_connect_role.arn

  connector_configuration = {
    "connector.class" = "io.debezium.connector.mysql.MySqlConnector"
    "tasks.max"       = "1"
    "database.hostname" = "my-database.example.com"
    "database.port"     = "3306"
    "database.user"     = "debezium"
    "database.password" = "dbz"
    "database.server.id" = "184054"
    "database.server.name" = "my-server"
    "table.include.list" = "mydb.mytable"
    "database.history.kafka.bootstrap.servers" = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
    "database.history.kafka.topic" = "schema-changes.mydb"
  }

  kafka_cluster {
    apache_kafka_cluster {
      bootstrap_servers = aws_msk_cluster.msk_cluster.bootstrap_brokers_tls
      vpc {
        subnets = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1", "subnet-0123456789abcdef2"]
        security_groups = ["sg-0123456789abcdef0"]
      }
    }
  }

  plugin {
    name    = aws_mskconnect_custom_plugin.custom_plugin.name
    version = aws_mskconnect_custom_plugin.custom_plugin.latest_revision
  }
}
```

### Notes:
- Replace `"subnet-0123456789abcdef0"`, `"subnet-0123456789abcdef1"`, `"subnet-0123456789abcdef2"` with your actual subnet IDs.
- Replace `"sg-0123456789abcdef0"` with your actual security group ID.
- Replace `"arn:aws:s3:::my-bucket"` with the ARN of your S3 bucket where `debezium.zip` is stored.
- Ensure that the `debezium.zip` file is uploaded to the specified S3 bucket before running the Terraform configuration.
- Adjust the `connector_configuration` block as per your specific requirements for the Debezium connector.

