  network_acl_id = aws_network_acl.main_network_acl.id
  rule_number    = 100
  protocol       = "tcp"
  rule_action    = "allow"
  egress         = false
  from_port      = 22
  to_port        = 22
  cidr_block     = "0.0.0.0/0"

  tags = {
    Name = "IngressRule"
  }
}

resource "aws_network_acl_rule" "egress_rule" {
  network_acl_id = aws_network_acl.main_network_acl.id
  rule_number    = 100
  protocol       = "all"
  rule_action    = "allow"
  egress         = true
  cidr_block     = "0.0.0.0/0"

  tags = {
    Name = "EgressRule"
  }
}

resource "aws_subnet_network_acl_association" "subnet_acl_association" {
  subnet_id      = aws_subnet.main_subnet.id
  network_acl_id = aws_network_acl.main_network_acl.id
}
