```hcl
provider "aws" {
  region = "us-west-2"
}

# Define a custom parameter group for Neptune
resource "aws_neptune_parameter_group" "custom_neptune_parameter_group" {
  family = "neptune1"
  name   = "custom-neptune-parameter-group"

  parameter {
    name         = "neptune_enable_audit_log"
    value        = "1"
    apply_method = "pending-reboot"
  }

  tags = {
    Name = "CustomNeptuneParameterGroup"
  }
}

# Define a subnet group for Neptune
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0987654321fedcba0"]

  tags = {
    Name = "NeptuneSubnetGroup"
  }
}

# Create a Neptune cluster using the custom parameter group and subnet group
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "neptune-cluster"
  neptune_cluster_parameter_group_name = aws_neptune_parameter_group.custom_neptune_parameter_group.name
  subnet_group_name                   = aws_neptune_subnet_group.neptune_subnet_group.name
  engine                              = "neptune"
  engine_version                      = "1.2.0.1"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"

  tags = {
    Name = "NeptuneCluster"
  }
}
```

