```hcl
provider "aws" {
  region = "us-west-2"
}

# Define custom parameters for the Neptune cluster
resource "aws_neptune_parameter_group" "neptune_cluster_parameter_group" {
  name   = "custom-neptune-cluster-param-group"
  family = "neptune1"

  parameter {
    name         = "neptune_enable_audit_log"
    value        = "1"
    apply_method = "pending-reboot"
  }
}

# Define custom parameters for the Neptune instance
resource "aws_neptune_parameter_group" "neptune_instance_parameter_group" {
  name   = "custom-neptune-instance-param-group"
  family = "neptune1"

  parameter {
    name         = "neptune_query_timeout"
    value        = "240"
    apply_method = "immediate"
  }
}

# Define subnets for Neptune cluster
resource "aws_neptune_subnet_group" "neptune_subnet_group" {
  name       = "neptune-subnet-group"
  subnet_ids = ["subnet-0123456789abcdef0", "subnet-0fedcba9876543210"] # Example subnet IDs

  tags = {
    Name = "NeptuneSubnetGroup"
  }
}

# Create Neptune cluster with custom parameter group and subnet group
resource "aws_neptune_cluster" "neptune_cluster" {
  cluster_identifier                  = "my-neptune-cluster"
  neptune_cluster_parameter_group_name = aws_neptune_parameter_group.neptune_cluster_parameter_group.name
  neptune_subnet_group_name           = aws_neptune_subnet_group.neptune_subnet_group.name
  engine                              = "neptune"
  engine_version                      = "1.2.0.1"
  backup_retention_period             = 5
  preferred_backup_window             = "07:00-09:00"
}

# Create Neptune instance in the cluster with its own custom parameter group
resource "aws_neptune_cluster_instance" "neptune_instance" {
  identifier                        = "my-neptune-instance"
  cluster_identifier                = aws_neptune_cluster.neptune_cluster.id
  instance_class                    = "db.r5.large"
  neptune_parameter_group_name      = aws_neptune_parameter_group.neptune_instance_parameter_group.name
  neptune_subnet_group_name         = aws_neptune_subnet_group.neptune_subnet_group.name
  apply_immediately                 = true
}

# Define security group to allow connections from example subnet
resource "aws_security_group" "neptune_security_group" {
  name        = "neptune-sg"
  description = "Security group for Neptune instance"
  vpc_id      = "vpc-0123456789abcdef0" # Example VPC ID

  tags = {
    Name = "NeptuneSG"
  }
}

# Allow ingress traffic from example subnet to Neptune instance
resource "aws_security_group_rule" "neptune_ingress_rule" {
  type                     = "ingress"
  from_port                = 8182
  to_port                  = 8182
  protocol                 = "tcp"
  security_group_id        = aws_security_group.neptune_security_group.id
  source_security_group_id = "sg-0123456789abcdef0" # Example source security group ID
}
```

### Notes:
- Replace `"subnet-0123456789abcdef0"` and `"subnet-0fedcba9876543210"` with your actual subnet IDs.
- Replace `"vpc-0123456789abcdef0"` with your actual VPC ID.
- Replace `"sg-0123456789abcdef0"` with the security group ID of the subnet from which you want to allow connections to the Neptune instance.
- The Neptune instance class `db.r5.large` is used here as an example. You can choose a different instance class based on your requirements.
- The Neptune engine version `1.2.0.1` is used here as an example. Ensure that the version is compatible with your requirements and available in your region.

