Below is a complete Terraform HCL program that creates an AWS Redshift cluster with endpoint access from two subnets in different availability zones. The program includes the necessary resources and dependencies as per the provided graph.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "redshift_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "redshift-vpc"
  }
}

resource "aws_subnet" "subnet_1" {
  vpc_id                  = aws_vpc.redshift_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "redshift-subnet-1"
  }
}

resource "aws_subnet" "subnet_2" {
  vpc_id                  = aws_vpc.redshift_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "redshift-subnet-2"
  }
}

resource "aws_security_group" "redshift_sg" {
  vpc_id = aws_vpc.redshift_vpc.id
  name   = "redshift-sg"

  ingress {
    from_port   = 5439
    to_port     = 5439
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # Adjust this to your specific needs
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "redshift-sg"
  }
}

resource "aws_redshift_subnet_group" "redshift_subnet_group" {
  name       = "redshift-subnet-group"
  subnet_ids = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id]
  tags = {
    Name = "redshift-subnet-group"
  }
}

resource "aws_redshift_cluster" "redshift_cluster" {
  cluster_identifier        = "redshift-cluster"
  node_type                 = "dc2.large"
  master_username           = "admin"
  master_password           = "yourStrong(!)Password123"
  cluster_subnet_group_name = aws_redshift_subnet_group.redshift_subnet_group.name
  vpc_security_group_ids    = [aws_security_group.redshift_sg.id]
  iam_roles                 = [] # Add IAM roles if necessary
  tags = {
    Name = "redshift-cluster"
  }
}
```

### Explanation:
- **Provider Configuration**: Configured to use the AWS provider in the `us-west-2` region.
- **VPC**: Created a VPC with a CIDR block of `10.0.0.0/16`.
- **Subnets**: Created two subnets in different availability zones (`us-west-2a` and `us-west-2b`) with CIDR blocks `10.0.1.0/24` and `10.0.2.0/24`.
- **Security Group**: Created a security group allowing inbound traffic on port 5439 (Redshift default port) from any IP (`0.0.0.0/0`). Adjust the `cidr_blocks` as needed for your security requirements.
- **Redshift Subnet Group**: Created a subnet group containing the two subnets.
- **Redshift Cluster**: Created a Redshift cluster with the specified node type, master username, and password. The cluster uses the created subnet group and security group.

Make sure to replace `"yourStrong(!)Password123"` with a strong password of your choice. Also, consider adding IAM roles if your Redshift cluster requires them for additional functionality.

