Below is the complete Terraform HCL program that creates an S3 bucket for storing images and sets up an IAM role with a policy to manage access to the S3 bucket.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "image_storage_bucket" {
  bucket = "my-website-images-bucket"
  acl    = "public-read"

  website {
    index_document = "index.html"
    error_document = "error.html"
  }

  tags = {
    Name        = "ImageStorageBucket"
    Environment = "production"
  }
}

resource "aws_iam_policy" "s3_access_policy" {
  name        = "S3AccessPolicy"
  description = "Policy to allow access to the image storage S3 bucket"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect   = "Allow"
        Action   = [
          "s3:GetObject",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Resource = [
          aws_s3_bucket.image_storage_bucket.arn,
          "${aws_s3_bucket.image_storage_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role" "s3_access_role" {
  name = "S3AccessRole"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "ec2.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  tags = {
    Name        = "S3AccessRole"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_role" {
  policy_arn = aws_iam_policy.s3_access_policy.arn
  role       = aws_iam_role.s3_access_role.name
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **S3 Bucket**: An S3 bucket named `my-website-images-bucket` is created with public read access. It also includes website configuration settings for serving static content.
- **IAM Policy**: An IAM policy named `S3AccessPolicy` is created to allow `GetObject`, `PutObject`, and `DeleteObject` actions on the S3 bucket.
- **IAM Role**: An IAM role named `S3AccessRole` is created with an assume role policy that allows EC2 instances to assume this role.
- **IAM Role Policy Attachment**: The `S3AccessPolicy` is attached to the `S3AccessRole`.

This configuration ensures that the S3 bucket is set up for storing images and that there is an IAM role with the necessary permissions to manage the bucket.

