```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "mybucket-source"
  acl    = "private"

  tags = {
    Name        = "SourceBucket"
    Environment = "dev"
  }
}

resource "aws_s3_bucket" "destination_bucket" {
  bucket = "mybucket-destination"
  acl    = "private"

  tags = {
    Name        = "DestinationBucket"
    Environment = "dev"
  }
}

resource "aws_iam_role" "analytics_role" {
  name = "s3-analytics-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "S3AnalyticsRole"
    Environment = "dev"
  }
}

resource "aws_iam_policy" "analytics_policy" {
  name = "s3-analytics-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.source_bucket.arn,
          "${aws_s3_bucket.source_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.destination_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name        = "S3AnalyticsPolicy"
    Environment = "dev"
  }
}

resource "aws_iam_role_policy_attachment" "attach_analytics_policy" {
  policy_arn = aws_iam_policy.analytics_policy.arn
  role       = aws_iam_role.analytics_role.name
}

resource "aws_s3_bucket_analytics_configuration" "analytics_config" {
  bucket = aws_s3_bucket.source_bucket.id
  name   = "entire-bucket-analytics"

  storage_class_analysis {
    data_export {
      output_schema_version = "V_1"
      destination {
        s3_bucket_destination {
          format     = "CSV"
          bucket_arn = aws_s3_bucket.destination_bucket.arn
          prefix     = "analytics/"
        }
      }
    }
  }
