Below is the complete Terraform HCL program that creates two S3 buckets, an IAM role, an IAM policy, attaches the policy to the role, and configures a weekly CSV inventory report for the source bucket, storing the report in the inventory bucket.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "source_bucket" {
  bucket = "my-source-bucket-unique-name"
  versioning {
    enabled = true
  }
}

resource "aws_s3_bucket" "inventory_bucket" {
  bucket = "my-inventory-bucket-unique-name"
}

resource "aws_iam_role" "s3_inventory_role" {
  name = "s3-inventory-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_inventory_policy" {
  name = "s3-inventory-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:PutObjectAcl"
        ]
        Effect = "Allow"
        Resource = "${aws_s3_bucket.inventory_bucket.arn}/*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_inventory_policy" {
  policy_arn = aws_iam_policy.s3_inventory_policy.arn
  role       = aws_iam_role.s3_inventory_role.name
}

resource "aws_s3_bucket_inventory" "weekly_inventory" {
  bucket = aws_s3_bucket.source_bucket.id
  name   = "weekly-inventory-report"

  included_object_versions = "Current"

  schedule {
    frequency = "Weekly"
  }

  destination {
    s3_bucket_destination {
      format     = "CSV"
      bucket_arn = aws_s3_bucket.inventory_bucket.arn
      prefix     = "inventory/"
    }
  }
}
```

This Terraform configuration ensures that all necessary resources are created and properly linked to fulfill the requirement of generating a weekly CSV inventory report for the source bucket and storing it in the inventory bucket. The IAM role and policy are set up to allow S3 to write to the inventory bucket.

