  # Ensure the bucket is created with private access
  acl = "private"

  # Configure logging to store access logs in the access_logs_bucket
  logging {
    target_bucket = aws_s3_bucket.access_logs_bucket.id
    target_prefix = "log/"
  }

  # Optional: Enable versioning for the main bucket
  versioning {
    enabled = true
  }

  # Optional: Enable server-side encryption for the main bucket
