  name = "codebuild-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "CodeBuildServiceRole"
    Environment = "dev"
  }
}

resource "aws_iam_policy" "codebuild_policy" {
  name = "codebuild-policy"

