Below is the complete Terraform HCL program that sets up the infrastructure for an autograder using AWS CodeBuild and AWS VPC, ensuring that the students' code does not have internet access.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "autograder_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "autograder-vpc"
  }
}

resource "aws_subnet" "autograder_subnet" {
  vpc_id                  = aws_vpc.autograder_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = false
  tags = {
    Name = "autograder-subnet"
  }
}

resource "aws_security_group" "autograder_sg" {
  vpc_id = aws_vpc.autograder_vpc.id
  name   = "autograder-sg"

  # Deny all outbound traffic
  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "autograder-sg"
  }
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "codebuild-role"
  }
}

resource "aws_iam_policy" "codebuild_policy" {
  name = "codebuild-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect = "Allow"
        Resource = "*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })

  tags = {
    Name = "codebuild-policy"
  }
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

resource "aws_codebuild_project" "autograder_codebuild" {
  name         = "autograder-codebuild"
  service_role = aws_iam_role.codebuild_role.arn

  source {
    type     = "GITHUB"
    location = "https://github.com/example/repo.git"
    auth {
      type = "OAUTH"
      resource = var.github_oauth_token
    }
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
    image        = "aws/codebuild/amazonlinux2-x86_64-standard:3.0"
    type         = "LINUX_CONTAINER"
  }

  vpc_config {
    vpc_id            = aws_vpc.autograder_vpc.id
    subnets           = [aws_subnet.autograder_subnet.id]
    security_group_ids = [aws_security_group.autograder_sg.id]
  }

  tags = {
    Name = "autograder-codebuild"
  }
}

variable "github_oauth_token" {
  description = "GitHub OAuth token for accessing the repository"
  default     = "your_github_oauth_token_here"
}
```

### Explanation:
- **VPC and Subnet**: A VPC (`autograder_vpc`) and a subnet (`autograder_subnet`) are created within the VPC. The subnet is configured to not assign public IPs to instances launched within it.
- **Security Group**: A security group (`autograder_sg`) is created to deny all outbound traffic, ensuring that the CodeBuild environment has no internet access.
- **IAM Role and Policy**: An IAM role (`codebuild_role`) and policy (`codebuild_policy`) are created to allow CodeBuild to perform necessary actions like logging and network interface management.
- **CodeBuild Project**: A CodeBuild project (`autograder_codebuild`) is set up to pull code from a GitHub repository and run it in the isolated environment defined by the VPC and security group.
- **Variable**: A variable `github_oauth_token` is used to pass the GitHub OAuth token for repository access. It has a default value that should be replaced with a real token before deployment.

