Below is the complete Terraform HCL program that meets the specified requirements. This program creates an S3 bucket, a VPC with a subnet, a security group with no ingress and egress, an IAM role and policy for CodeBuild, and a CodeBuild project configured to use these resources.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "codebuild_output_bucket" {
  bucket = "student-codebuild-output-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "main_subnet" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.0.0/24"
  map_public_ip_on_launch = false
}

resource "aws_security_group" "isolated_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "isolated-sg"

  # No ingress or egress rules to block internet access
}

resource "aws_iam_role" "codebuild_role" {
  name = "codebuild-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "codebuild.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "codebuild_policy" {
  name = "codebuild-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:PutObject",
          "s3:GetBucketAcl",
          "s3:PutBucketAcl"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.codebuild_output_bucket.arn}",
          "${aws_s3_bucket.codebuild_output_bucket.arn}/*"
        ]
      },
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      },
      {
        Action = [
          "ec2:CreateNetworkInterface",
          "ec2:DescribeNetworkInterfaces",
          "ec2:DeleteNetworkInterface"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_codebuild_policy" {
  policy_arn = aws_iam_policy.codebuild_policy.arn
  role       = aws_iam_role.codebuild_role.name
}

resource "aws_codebuild_project" "student_codebuild_project" {
  name         = "student-codebuild-project"
  service_role = aws_iam_role.codebuild_role.arn

  artifacts {
    type     = "S3"
    location = aws_s3_bucket.codebuild_output_bucket.bucket
  }

  environment {
    compute_type = "BUILD_GENERAL1_SMALL"
