Below is the complete Terraform HCL program that sets up the infrastructure as described in the prompt. This includes an S3 bucket for storing cat pictures, an IAM role and policy for a Lambda function to access the S3 bucket, the Lambda function itself, and an API Gateway to expose an endpoint for retrieving a random cat picture.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "cat_pictures_bucket" {
  bucket = "cat-pictures-bucket-unique-name"
  acl    = "private"

  versioning {
    enabled = true
  }
}

resource "aws_iam_role" "api_gateway_lambda_role" {
  name = "api-gateway-lambda-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "s3_access_policy" {
  name = "s3-access-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          aws_s3_bucket.cat_pictures_bucket.arn,
          "${aws_s3_bucket.cat_pictures_bucket.arn}/*"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_s3_policy_to_lambda_role" {
  policy_arn = aws_iam_policy.s3_access_policy.arn
  role       = aws_iam_role.api_gateway_lambda_role.name
}

resource "aws_lambda_function" "get_random_cat_picture" {
  function_name = "get-random-cat-picture"
  role          = aws_iam_role.api_gateway_lambda_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"

  environment {
    variables = {
      BUCKET_NAME = aws_s3_bucket.cat_pictures_bucket.bucket
    }
  }
}

resource "aws_api_gateway_rest_api" "cat_pictures_api" {
  name        = "cat-pictures-api"
  description = "API to get random cat pictures"
}

resource "aws_api_gateway_resource" "random_cat_picture_resource" {
  rest_api_id = aws_api_gateway_rest_api.cat_pictures_api.id
  parent_id   = aws_api_gateway_rest_api.cat_pictures_api.root_resource_id
  path_part   = "random-cat-picture"
}

resource "aws_api_gateway_method" "get_random_cat_picture_method" {
  rest_api_id   = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id   = aws_api_gateway_resource.random_cat_picture_resource.id
  http_method   = "GET"
  authorization = "NONE"
}

resource "aws_api_gateway_integration" "get_random_cat_picture_integration" {
  rest_api_id             = aws_api_gateway_rest_api.cat_pictures_api.id
  resource_id             = aws_api_gateway_resource.random_cat_picture_resource.id
  http_method             = aws_api_gateway_method.get_random_cat_picture_method.http_method
  integration_http_method = "POST"
  type                    = "AWS_PROXY"
  uri                     = aws_lambda_function.get_random_cat_picture.invoke_arn
}

resource "aws_lambda_permission" "allow_api_gateway_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromAPIGateway"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.get_random_cat_picture.function_name
  principal     = "apigateway.amazonaws.com"
  source_arn    = "${aws_api_gateway_rest_api.cat_pictures_api.execution_arn}/*/*/*"
}
```

### Notes:
- The `filename` attribute in the `aws_lambda_function` resource points to a zip file containing the Lambda function code. You need to ensure that this file exists and contains the necessary code to interact with S3 and return a random cat picture.
- The `source_arn` in the `aws_lambda_permission` resource uses the execution ARN of the API Gateway to allow it to invoke the Lambda function.
- The S3 bucket name (`cat-pictures-bucket-unique-name`) should be globally unique across all AWS accounts. You may need to change it to a unique name.
- The region is set to `us-west-2`, but you can change it to any other region as per your preference.

