      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "lambda_access_policy" {
  name = "lambda_access_policy"

  policy = jsonencode({
    Version = "2012-10-17"
