        Effect = "Allow"
        Resource = [
          aws_s3_bucket.cat_pictures_storage.arn,
          "${aws_s3_bucket.cat_pictures_storage.arn}/*"
        ]
      },
      {
        Action = [
          "dynamodb:PutItem",
          "dynamodb:GetItem",
          "dynamodb:Scan"
        ]
        Effect = "Allow"
        Resource = aws_dynamodb_table.cat_pictures_metadata.arn
      }
    ]
  })
}

