Below is the complete Terraform HCL program that provisions an EC2 instance and sets up AWS Backup to back it up every day at midnight. The program includes the necessary IAM roles, policies, and backup configurations.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "backup_service_role" {
  name = "backup-service-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "attach_backup_policy_to_role" {
  name       = "attach-backup-policy-to-role"
  roles      = [aws_iam_role.backup_service_role.name]
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSBackupDefaultServiceRolePolicyForBackup"
}

resource "aws_instance" "ec2_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID for Amazon Linux 2 in us-west-2
  instance_type = "t3.micro"
}

resource "aws_backup_vault" "backup_vault" {
  name = "daily-backup-vault"
}

resource "aws_backup_plan" "daily_backup_plan" {
  name = "daily-backup-plan"

  rule {
    rule_name         = "daily-backup-rule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 0 * * ? *)" # Daily at midnight UTC
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_service_role.arn
  name         = "daily-backup-selection"
  plan_id      = aws_backup_plan.daily_backup_plan.id

  resources = [aws_instance.ec2_instance.arn]
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `backup-service-role` is created with a trust relationship to allow AWS Backup to assume the role.
- **IAM Policy Attachment**: The `AWSBackupDefaultServiceRolePolicyForBackup` policy is attached to the IAM role to grant necessary permissions for AWS Backup.
- **EC2 Instance**: An EC2 instance is provisioned using an example AMI ID for Amazon Linux 2 in the `us-west-2` region with an instance type of `t3.micro`.
- **Backup Vault**: A backup vault named `daily-backup-vault` is created to store the backups.
- **Backup Plan**: A backup plan named `daily-backup-plan` is created with a cron expression to schedule daily backups at midnight UTC.
- **Backup Selection**: A backup selection named `daily-backup-selection` is created to include the EC2 instance in the backup plan.

This configuration ensures that the EC2 instance is backed up daily at midnight using AWS Backup.

