Below is the complete Terraform HCL program that meets the specified requirements. This program creates an AWS Lambda function, an AWS EventBridge rule with a cron schedule, an EventBridge target linking to the Lambda function, and the necessary permissions for EventBridge to invoke the Lambda function.

```hcl
provider "aws" {
  region = "us-west-2"  # Default region, can be changed as needed
}

# IAM Role for Lambda Execution
resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

# IAM Policy for Lambda Execution
resource "aws_iam_policy" "lambda_execution_policy" {
  name        = "lambda-execution-policy"
  description = "Policy for Lambda execution"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Effect   = "Allow"
        Resource = "arn:aws:logs:*:*:*"
      }
    ]
  })
}

# Attach the policy to the Lambda execution role
resource "aws_iam_role_policy_attachment" "lambda_execution_policy_attachment" {
  policy_arn = aws_iam_policy.lambda_execution_policy.arn
  role       = aws_iam_role.lambda_execution_role.name
}

# AWS Lambda Function
resource "aws_lambda_function" "cron" {
  function_name = "cron-lambda-function"
  filename      = "./supplement/lambda_func.zip"
  handler       = "lambda_func.lambda_handler"
  runtime       = "python3.12"
  role          = aws_iam_role.lambda_execution_role.arn
}

# AWS EventBridge Rule
resource "aws_cloudwatch_event_rule" "cron" {
  name                = "cron"
  schedule_expression = "cron(0 7 * * ? *)"  # Everyday at 7 UTC
}

# AWS EventBridge Target
resource "aws_cloudwatch_event_target" "cron" {
  rule      = aws_cloudwatch_event_rule.cron.name
  target_id = "cron-target"
  arn       = aws_lambda_function.cron.arn
}

# AWS Lambda Permission
resource "aws_lambda_permission" "cron" {
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.cron.function_name
  principal     = "events.amazonaws.com"
  source_arn    = aws_cloudwatch_event_rule.cron.arn
}
```

This Terraform configuration ensures that all required resources are created and properly linked, respecting the dependencies specified in the prompt. The IAM role and policy are set up to allow the Lambda function to execute and write logs to CloudWatch. The EventBridge rule is configured to trigger the Lambda function every day at 7 UTC.

