      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "sts:AssumeRole"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_streaming_distribution.arn
          }
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_cloudfront_oai_policy" {
  policy_arn = aws_iam_policy.cloudfront_oai_policy.arn
  role       = aws_iam_role.cloudfront_oai_role.name
}

resource "aws_cloudfront_distribution" "video_streaming_distribution" {
  enabled             = true
  comment             = "Video Streaming Distribution"
  is_ipv6_enabled     = true
  price_class         = "PriceClass_All"
