provider "aws" {
  region = "us-east-1"
}

resource "aws_s3_bucket" "video_content_bucket" {
  bucket = "video-content-bucket-netflix"
  acl    = "private"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "cloudfront.amazonaws.com"
        }
        Action = "s3:GetObject"
        Resource = "${aws_s3_bucket.video_content_bucket.arn}/*"
        Condition = {
          StringEquals = {
            "AWS:SourceArn" = aws_cloudfront_distribution.video_content_distribution.arn
          }
        }
      }
    ]
  })
}

resource "aws_cloudfront_origin_access_control" "video_content_oac" {
  name                           = "video-content-oac"
  origin_access_control_origin_type = "s3"
  signing_behavior               = "always"
  signing_protocol               = "sigv4"
}

resource "aws_cloudfront_distribution" "video_content_distribution" {
  enabled             = true
  price_class           = "PriceClass_200"
  wait_for_deployment = true

  origin {
    domain_name          = aws_s3_bucket.video_content_bucket.bucket_regional_domain_name
    origin_id            = "s3_video_content_origin"
    origin_access_control_id = aws_cloudfront_origin_access_control.video_content_oac.id
  }

  default_cache_behavior {
    allowed_methods  = ["GET", "HEAD"]
    cached_methods   = ["GET", "HEAD"]
    target_origin_id = "s3_video_content_origin"
    viewer_protocol_policy = "allow-all"
  }

  restrictions {
    geo_restriction {
      restriction_type = "whitelist"
      locations        = ["US", "CA", "GB", "DE"]
    }
  }

  viewer_certificate {
    cloudfront_default_certificate = true
  }
}

resource "aws_route53_zone" "netflix_com_zone" {
  name = "netflix.com"
}

resource "aws_route53_record" "cloudfront_dns_record_a" {
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  name    = "video.netflix.com"
  type    = "A"

  alias {
    name                   = aws_cloudfront_distribution.video_content_distribution.domain_name
    zone_id                = aws_cloudfront_distribution.video_content_distribution.hosted_zone_id
    evaluate_target_health = false
  }
}

resource "aws_route53_record" "cloudfront_dns_record_cname" {
  zone_id = aws_route53_zone.netflix_com_zone.zone_id
  name    = "cdn.netflix.com"
  type    = "CNAME"

  records = [aws_cloudfront_distribution.video_content_distribution.domain_name]
}
