resource "aws_subnet" "subnet_2" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.5.0/24"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_3" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.6.0/24"
  map_public_ip_on_launch = true
}

resource "aws_security_group" "main_sg" {
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = [aws_vpc.main_vpc.cidr_block]
  }

  egress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

resource "aws_lb" "application_lb" {
  name               = "application-lb"
  internal           = false
  load_balancer_type = "application"
  security_groups    = [aws_security_group.main_sg.id]
  subnets            = [aws_subnet.subnet_1.id, aws_subnet.subnet_2.id, aws_subnet.subnet_3.id]

  enable_deletion_protection = false
}

resource "aws_lb_target_group" "tg_http" {
  name     = "tg-http"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main_vpc.id
}

resource "aws_lb_listener" "listener_http" {
  load_balancer_arn = aws_lb.application_lb.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.tg_http.arn
  }
}

resource "aws_instance" "ubuntu_instance" {
  ami           = "ami-0c55b159cbfafe1f0" # Example AMI ID for Ubuntu in us-west-2
  instance_type = "t3.micro"
  subnet_id     = aws_subnet.subnet_1.id

  tags = {
    Name = "UbuntuInstance"
  }
}

resource "aws_lb_target_group_attachment" "tg_attachment" {
  target_group_arn = aws_lb_target_group.tg_http.arn
  target_id        = aws_instance.ubuntu_instance.id
  port             = 80
}

resource "aws_route53_zone" "video_stream_zone" {
  name = "test-video-stream.com"
}

resource "aws_route53_record" "lb_ipv4_alias" {
  zone_id = aws_route53_zone.video_stream_zone.zone_id
  name    = "lb.test-video-stream.com"
  type    = "A"

  alias {
    name                   = aws_lb.application_lb.dns_name
    zone_id                = aws_lb.application_lb.zone_id
    evaluate_target_health = true
  }
}

resource "aws_route53_record" "lb_ipv6_alias" {
  zone_id = aws_route53_zone.video_stream_zone.zone_id
  name    = "lb.test-video-stream.com"
  type    = "AAAA"

  alias {
    name                   = aws_lb.application_lb.dns_name
    zone_id                = aws_lb.application_lb.zone_id
    evaluate_target_health = true
  }
}
```

This Terraform configuration creates all the necessary resources as per the provided requirements and ensures that all dependencies are correctly managed. The AMI ID used for the EC2 instance is an example and should be replaced with the appropriate AMI ID for your specific region and requirements.

