Below is the complete Terraform HCL program that sets up a VPC with public subnets and security groups for database access. It also creates a PostgreSQL database instance within the VPC, accessible and secured by a designated security group.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "MainVPC"
  }
}

resource "aws_subnet" "public_subnet_1" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "PublicSubnet1"
  }
}

resource "aws_security_group" "db_access_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "DBAccessSG"

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict this in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "DBAccessSG"
  }
}

resource "aws_db_instance" "postgres_db" {
  instance_class = "db.t3.micro"
  allocated_storage = 20
  engine = "postgres"
  engine_version = "13.4"
  name = "mydb"
  username = "dbadmin"
  password = "securepassword123"
  db_subnet_group_name = aws_db_subnet_group.postgres_subnets.name
  vpc_security_group_ids = [aws_security_group.db_access_sg.id]

  tags = {
    Name = "PostgresDB"
  }
}

resource "aws_db_subnet_group" "postgres_subnets" {
  name       = "postgres-subnets"
  subnet_ids = [aws_subnet.public_subnet_1.id]

  tags = {
    Name = "PostgresSubnets"
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC named `MainVPC` is created with a CIDR block of `10.0.0.0/16`.
- **Public Subnet**: A public subnet named `PublicSubnet1` is created within the VPC with a CIDR block of `10.0.1.0/24`. The `map_public_ip_on_launch` attribute is set to `true` to ensure instances launched in this subnet receive a public IP.
- **Security Group**: A security group named `DBAccessSG` is created to allow inbound traffic on port 5432 (PostgreSQL default port) from any IP (`0.0.0.0/0`). This should be restricted in a production environment.
- **DB Subnet Group**: A DB subnet group named `postgres-subnets` is created to associate the public subnet with the RDS instance.
- **PostgreSQL Database Instance**: A PostgreSQL database instance named `PostgresDB` is created within the VPC using the `db.t3.micro` instance class. It uses the previously created subnet group and security group for network configuration. The database is initialized with a default database name `mydb`, username `dbadmin`, and a password `securepassword123`.

This configuration ensures that the PostgreSQL database is properly set up within the VPC and is accessible via the defined security group.

