Below is the complete Terraform HCL program that provisions a secure PostgreSQL database instance within a specified AWS VPC, leveraging AWS services like RDS, subnets, and KMS for encryption. The configuration includes a custom parameter group, a security group, and a DB subnet group.

```hcl
provider "aws" {
  region = "us-west-2"
}

# Create a KMS key for encrypting the RDS instance
resource "aws_kms_key" "database_encryption_key" {
  description             = "KMS key for encrypting the RDS instance"
  enable_key_rotation     = true
  deletion_window_in_days = 10
}

# Create a custom parameter group for PostgreSQL settings
resource "aws_db_parameter_group" "custom_postgresql_parameter_group" {
  name   = "custom-postgresql-parameter-group"
  family = "postgres15"

  parameter {
    name  = "max_connections"
    value = "200"
  }

  parameter {
    name  = "shared_buffers"
    value = "4GB"
  }
}

# Create a security group to manage access to the RDS instance
resource "aws_security_group" "rds_security_group" {
  description = "Security group for RDS instance"
  vpc_id      = "vpc-12345678" # Replace with your VPC ID

  ingress {
    from_port   = 5432
    to_port     = 5432
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"] # Replace with your trusted IP range
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }
}

# Create a DB subnet group for placing the RDS instance within the VPC
resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = ["subnet-12345678", "subnet-87654321"] # Replace with your subnet IDs

  tags = {
    Name = "RDS Subnet Group"
  }
}

# Create a secure PostgreSQL RDS instance with specified configurations
resource "aws_db_instance" "secure_postgresql_db" {
  allocated_storage    = 50
  engine               = "postgres"
  engine_version       = "15"
  instance_class       = "db.t3.medium"
  name                 = "secure-postgresql-db"
  username             = "dbadmin"
  password             = "securepassword123" # Replace with a secure password
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]
  multi_az             = true
  storage_encrypted    = true
  kms_key_id           = aws_kms_key.database_encryption_key.key_id
  parameter_group_name = aws_db_parameter_group.custom_postgresql_parameter_group.name

  tags = {
    Name = "Secure PostgreSQL DB"
  }
}
```

### Notes:
- Replace `"vpc-12345678"` with your actual VPC ID.
- Replace `["subnet-12345678", "subnet-87654321"]` with your actual subnet IDs.
- Replace `"10.0.0.0/16"` with your trusted IP range for database access.
- Replace `"securepassword123"` with a secure password for the database administrator.
- Ensure that the subnets provided are part of the specified VPC and are properly configured for RDS usage.

