Below is the complete Terraform HCL program that defines an AWS RDS option group named "option-group-pike" with the specified requirements. The program includes the necessary IAM role and policy attachments to support the `SQLSERVER_AUDIT` option.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "rds_option_group_role" {
  name = "rds-option-group-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "rds_option_group_policy" {
  name = "rds-option-group-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          "arn:aws:s3:::example-bucket/*",
          "arn:aws:s3:::example-bucket"
        ]
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_rds_option_group_policy" {
  policy_arn = aws_iam_policy.rds_option_group_policy.arn
  role       = aws_iam_role.rds_option_group_role.name
}

resource "aws_rds_option_group" "option_group_pike" {
  name              = "option-group-pike"
  engine_name       = "sqlserver-ee"
  major_engine_version = "11"

  option {
    option_name = "SQLSERVER_AUDIT"
    option_settings {
      name  = "S3BucketName"
      value = "example-bucket"
    }
    option_settings {
      name  = "S3BucketPrefix"
      value = "audit-logs/"
    }
    option_settings {
      name  = "AuditFileFormat"
      value = "CSV"
    }
    option_settings {
      name  = "LogRetentionPeriod"
      value = "14"
    }
    option_settings {
      name  = "RoleArn"
      value = aws_iam_role.rds_option_group_role.arn
    }
  }

  option {
    option_name = "TDE"
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **IAM Role**: An IAM role named `rds-option-group-role` is created with a trust relationship allowing RDS to assume the role.
- **IAM Policy**: An IAM policy named `rds-option-group-policy` is created with permissions to access an S3 bucket (`example-bucket`).
- **IAM Role Policy Attachment**: The policy is attached to the IAM role.
- **RDS Option Group**: An RDS option group named `option-group-pike` is created for the `sqlserver-ee` engine with major version `11`. It includes options for `SQLSERVER_AUDIT` and `TDE`. The `SQLSERVER_AUDIT` option is configured with settings including the S3 bucket name, prefix, file format, log retention period, and the IAM role ARN.

