Below is the complete Terraform HCL program that sets up an AWS RDS Aurora MySQL cluster with a proxy, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The configuration is designed to be deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "aurora_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "aurora-vpc"
  }
}

resource "aws_subnet" "aurora_subnet_1" {
  vpc_id                  = aws_vpc.aurora_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "aurora-subnet-1"
  }
}

resource "aws_subnet" "aurora_subnet_2" {
  vpc_id                  = aws_vpc.aurora_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "aurora-subnet-2"
  }
}

resource "aws_security_group" "aurora_sg" {
  vpc_id = aws_vpc.aurora_vpc.id
  name   = "aurora-sg"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "aurora-sg"
  }
}

resource "aws_db_subnet_group" "aurora_subnet_group" {
  name       = "aurora-subnet-group"
  subnet_ids = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  tags = {
    Name = "aurora-subnet-group"
  }
}

resource "aws_secretsmanager_secret" "aurora_credentials" {
  name        = "aurora-credentials"
  description = "Credentials for Aurora RDS Cluster"
  tags = {
    Name = "aurora-credentials"
  }
}

resource "aws_secretsmanager_secret_version" "aurora_credentials_version" {
  secret_id     = aws_secretsmanager_secret.aurora_credentials.id
  secret_string = jsonencode({ username = "admin", password = "securepassword123" })
}

resource "aws_iam_role" "aurora_proxy_role" {
  name = "aurora-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "aurora-proxy-role"
  }
}

resource "aws_iam_policy_attachment" "aurora_proxy_policy_attachment" {
  name       = "aurora-proxy-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSProxyFullAccess"
  roles      = [aws_iam_role.aurora_proxy_role.name]
}

resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  master_username         = jsondecode(aws_secretsmanager_secret_version.aurora_credentials_version.secret_string)["username"]
  master_password         = jsondecode(aws_secretsmanager_secret_version.aurora_credentials_version.secret_string)["password"]
  backup_retention_period = 5
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.aurora_sg.id]
  tags = {
    Name = "aurora-cluster"
  }
}

resource "aws_rds_cluster_instance" "aurora_instance_1" {
  identifier              = "aurora-instance-1"
  cluster_identifier      = aws_rds_cluster.aurora_cluster.id
  engine                  = aws_rds_cluster.aurora_cluster.engine
  instance_class          = "db.r5.large"
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  publicly_accessible     = false
  tags = {
    Name = "aurora-instance-1"
  }
}

resource "aws_rds_cluster_instance" "aurora_instance_2" {
  identifier              = "aurora-instance-2"
  cluster_identifier      = aws_rds_cluster.aurora_cluster.id
  engine                  = aws_rds_cluster.aurora_cluster.engine
  instance_class          = "db.r5.large"
  db_subnet_group_name    = aws_db_subnet_group.aurora_subnet_group.name
  publicly_accessible     = false
  tags = {
    Name = "aurora-instance-2"
  }
}

resource "aws_db_proxy" "aurora_proxy" {
  name                   = "aurora-proxy"
  engine_family          = "MYSQL"
  role_arn               = aws_iam_role.aurora_proxy_role.arn
  vpc_subnet_ids         = [aws_subnet.aurora_subnet_1.id, aws_subnet.aurora_subnet_2.id]
  vpc_security_group_ids = [aws_security_group.aurora_sg.id]

  auth {
    auth_scheme    = "SECRETS"
    secret_arn     = aws_secretsmanager_secret.aurora_credentials.arn
    iam_auth       = "DISABLED"
    description    = "Aurora Proxy Auth"
    username       = jsondecode(aws_secretsmanager_secret_version.aurora_credentials_version.secret_string)["username"]
  }

  tags = {
    Name = "aurora-proxy"
  }
}
```

