Below is the complete Terraform HCL program that sets up an AWS RDS Aurora MySQL cluster with a proxy, including VPC, subnets, security groups, IAM roles, and Secrets Manager for secure credential storage. The backup retention period for the RDS cluster is set to 5 days, and the preferred backup window is from 7 AM to 9 AM.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = false
  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = false
  tags = {
    Name = "subnet-b"
  }
}

resource "aws_security_group" "rds_sg" {
  vpc_id = aws_vpc.main_vpc.id
  name   = "rds-security-group"

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["10.0.0.0/16"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-sg"
  }
}

resource "aws_iam_role" "rds_proxy_role" {
  name = "rds-proxy-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name = "rds-proxy-role"
  }
}

resource "aws_iam_policy_attachment" "rds_proxy_policy_attachment" {
  name       = "rds-proxy-policy-attachment"
  policy_arn = "arn:aws:iam::aws:policy/service-role/AmazonRDSProxyServiceRolePolicy"
  roles      = [aws_iam_role.rds_proxy_role.name]
}

resource "aws_secretsmanager_secret" "db_credentials" {
  name = "db-credentials"

  tags = {
    Name = "db-credentials"
  }
}

resource "aws_db_subnet_group" "db_subnet_group" {
  name       = "db-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "db-subnet-group"
  }
}

resource "aws_rds_cluster" "aurora_cluster" {
  cluster_identifier      = "aurora-cluster"
  engine                  = "aurora-mysql"
  engine_version          = "5.7.mysql_aurora.2.10.2"
  master_username         = "admin"
  master_password         = "securepassword123"
  backup_retention_period = 5
  preferred_backup_window = "07:00-09:00"
  db_subnet_group_name    = aws_db_subnet_group.db_subnet_group.name
  vpc_security_group_ids  = [aws_security_group.rds_sg.id]

  tags = {
    Name = "aurora-cluster"
  }
}

resource "aws_rds_cluster_instance" "aurora_instance" {
  count              = 2
  identifier         = "aurora-instance-${count.index}"
  cluster_identifier = aws_rds_cluster.aurora_cluster.id
  engine             = aws_rds_cluster.aurora_cluster.engine
  instance_class     = "db.t3.medium"
  db_subnet_group_name = aws_db_subnet_group.db_subnet_group.name

  tags = {
    Name = "aurora-instance-${count.index}"
  }
}

resource "aws_db_proxy" "rds_proxy" {
  name               = "rds-proxy"
  engine_family      = "MYSQL"
  role_arn           = aws_iam_role.rds_proxy_role.arn
  vpc_subnet_ids     = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
  vpc_security_group_ids = [aws_security_group.rds_sg.id]

  auth {
    auth_scheme    = "SECRETS"
    secret_arn     = aws_secretsmanager_secret.db_credentials.arn
    iam_auth       = "DISABLED"
    description    = "RDS Proxy authentication"
  }

  tags = {
    Name = "rds-proxy"
  }
}
