  roles      = [aws_iam_role.lightsail_database_role.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
}

resource "aws_lightsail_database" "mysql_database" {
  relational_database_name = "my-mysql-database"
  blueprint_id             = "mysql_8_0"
  bundle_id                = "medium_1_0"
  master_database_name     = "mydb"
  master_username          = "admin"
  master_password          = "securepassword123"

  preferred_backup_window    = "16:00-16:30"
