    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy_attachment" "attach_lightsail_policy" {
  name       = "attach-lightsail-policy"
  roles      = [aws_iam_role.lightsail_instance_role.name]
  policy_arn = "arn:aws:iam::aws:policy/AmazonLightsailFullAccess"
}

resource "aws_lightsail_instance" "example_lightsail_instance" {
  name              = "example-lightsail-instance"
  availability_zone = "us-east-1a"
  blueprint_id      = "amazon_linux_2"
  bundle_id         = "nano_1_0"
}

resource "aws_lightsail_disk" "additional_disk_1" {
