  availability_zone = aws_lightsail_instance.example_lightsail_instance.availability_zone
  size_in_gb     = 30
}

resource "aws_lightsail_disk_attachment" "attach_disk_1" {
  disk_name     = aws_lightsail_disk.additional_disk_1.name
  instance_name = aws_lightsail_instance.example_lightsail_instance.name
  disk_path     = "/dev/xvdf"
}

resource "aws_lightsail_disk_attachment" "attach_disk_2" {
  disk_name     = aws_lightsail_disk.additional_disk_2.name
  instance_name = aws_lightsail_instance.example_lightsail_instance.name
  disk_path     = "/dev/xvdg"
}
```

