resource "aws_iam_role" "lightsail_bucket_access_role" {
  name = "lightsail-bucket-access-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lightsail.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "bucket_access_policy" {
  name = "bucket-access-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect = "Allow"
        Resource = [
          aws_s3_bucket.accessed_bucket.arn,
          "${aws_s3_bucket.accessed_bucket.arn}/*"
        ]
      }
    ]
  })
}

