Below is the complete Terraform HCL program that sets up an S3 Glacier vault for long-term data archiving, including the necessary IAM roles and policies, and the S3 bucket lifecycle configuration.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "glacier_vault_bucket" {
  bucket = "my-glacier-vault-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_iam_role" "glacier_transition_role" {
  name = "glacier-transition-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "s3.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "glacier_transition_policy" {
  name = "glacier-transition-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "glacier:InitiateMultipartUpload",
          "glacier:UploadMultipartPart",
          "glacier:CompleteMultipartUpload",
          "glacier:AbortMultipartUpload",
          "glacier:GetVaultLock",
          "glacier:GetJobOutput",
          "glacier:CreateVault",
          "glacier:DescribeVault",
          "glacier:GetVaultAccessPolicy",
          "glacier:DeleteArchive",
          "glacier:InitiateJob",
          "glacier:ListJobs",
          "glacier:GetVaultNotifications",
          "glacier:DeleteVaultAccessPolicy",
          "glacier:DescribeJob",
          "glacier:UploadArchive",
          "glacier:DeleteVaultNotifications",
          "glacier:SetDataRetrievalPolicy",
          "glacier:GetDataRetrievalPolicy",
          "glacier:SetVaultAccessPolicy",
          "glacier:SetVaultNotifications"
        ]
        Effect   = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_glacier_transition_policy" {
  policy_arn = aws_iam_policy.glacier_transition_policy.arn
  role       = aws_iam_role.glacier_transition_role.name
}

resource "aws_s3_bucket_lifecycle_configuration" "glacier_vault_lifecycle" {
  bucket = aws_s3_bucket.glacier_vault_bucket.id

  rule {
    id     = "transition-to-glacier"
    status = "Enabled"

    transition {
      days          = 30
      storage_class = "GLACIER"
    }
  }
}
```

This Terraform configuration creates an S3 bucket named `my-glacier-vault-bucket` with versioning and server-side encryption enabled. It also sets up an IAM role and policy that allows S3 to transition objects to Glacier after 30 days. The lifecycle configuration is applied to the bucket to automate the transition process.

