Below is the complete Terraform HCL program that sets up an S3 bucket for long-term data storage and configures AWS Backup to back up this bucket. The program includes the necessary IAM roles and policies, as well as the backup vault, plan, and selection.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "long_term_storage_bucket" {
  bucket = "my-long-term-storage-bucket"
  acl    = "private"

  versioning {
    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }

  tags = {
    Name        = "LongTermStorageBucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "BackupRole"
    Environment = "production"
  }
}

resource "aws_iam_policy" "backup_policy" {
  name = "backup-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket",
          "s3:PutObject",
          "s3:DeleteObject"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.long_term_storage_bucket.arn}",
          "${aws_s3_bucket.long_term_storage_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name        = "BackupPolicy"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "attach_backup_policy_to_role" {
  policy_arn = aws_iam_policy.backup_policy.arn
  role       = aws_iam_role.backup_role.name
}

resource "aws_backup_vault" "backup_vault" {
  name = "my-backup-vault"

  tags = {
    Name        = "MyBackupVault"
    Environment = "production"
  }
}

resource "aws_backup_plan" "backup_plan" {
  name = "my-backup-plan"

  rule {
    rule_name         = "DailyBackupRule"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 23 * * ? *)"
    start_window      = 3600
    completion_window = 43200

    recovery_point_tags = {
      Name        = "DailyBackup"
      Environment = "production"
    }
  }

  tags = {
    Name        = "MyBackupPlan"
    Environment = "production"
  }
}

resource "aws_backup_selection" "backup_selection" {
