    enabled = true
  }

  server_side_encryption_configuration {
    rule {
      apply_server_side_encryption_by_default {
        sse_algorithm = "AES256"
      }
    }
  }
}

resource "aws_s3_bucket_lifecycle_configuration" "glacier_lifecycle_config" {
  bucket = aws_s3_bucket.glacier_vault_bucket.id

  rule {
    id     = "transition-to-glacier"
    status = "Enabled"

    transition {
      days          = 30
      storage_class = "GLACIER"
    }
  }
}

resource "aws_iam_policy" "glacier_access_policy" {
  name        = "GlacierAccessPolicy"
  description = "Policy to allow access to the Glacier vault"

