Below is the complete Terraform HCL program that creates an Application Load Balancer along with the necessary VPC and subnets. The program adheres to the requirements and dependencies specified in the prompt.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true

  tags = {
    Name = "example-subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = true

  tags = {
    Name = "example-subnet-b"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "example-alb"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
  enable_http2       = true
  idle_timeout       = 60
  enable_deletion_protection = false

  tags = {
    Name = "example-alb"
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.vpc.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Subnets**: Two subnets (`subnet_a` and `subnet_b`) are created within the VPC, each in different availability zones (`us-west-2a` and `us-west-2b`).
- **Application Load Balancer (ALB)**: An ALB named `example-alb` is created, using the subnets created earlier. It listens on port 80 and has HTTP/2 enabled.
- **Security Group**: A security group (`alb_sg`) is created to allow inbound traffic on port 80 from any IP address (`0.0.0.0/0`) and outbound traffic to any destination.

This configuration ensures that all required resources are created in the correct order and with the necessary dependencies.

