Below is a complete Terraform HCL program that creates an Elastic IP and an Application Load Balancer using the allocated Elastic IP. The program includes the necessary dependencies and configurations based on the provided schema summary.

```hcl
provider "aws" {
  region = "us-west-2"  # Specify your desired region
}

resource "aws_eip" "load_balancer_eip" {
  vpc = true  # Allocate the EIP in a VPC
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-${count.index}"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = aws_subnet.public[*].id
  ip_address_type    = "ipv4"
  load_balancer_type = "application"

  enable_http2 = true

  subnet_mapping {
    subnet_id     = aws_subnet.public[0].id
    allocation_id = aws_eip.load_balancer_eip.allocation_id
  }

  tags = {
    Name = "my-application-load-balancer"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "lb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lb-sg"
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured with the `us-west-2` region. You can change this to any region that supports Elastic IPs and Application Load Balancers.
2. **Elastic IP (EIP)**: An Elastic IP is created and allocated within a VPC.
3. **VPC and Subnets**: A VPC and two public subnets are created to host the Application Load Balancer.
4. **Application Load Balancer (ALB)**: An Application Load Balancer is created with HTTP2 enabled and associated with the Elastic IP via a subnet mapping.
5. **Security Group**: A security group is created to allow HTTP traffic on port 80 from any IP address (`0.0.0.0/0`). This is a basic setup and should be adjusted for production environments to restrict access appropriately.

This configuration ensures that the Load Balancer is created with the specified Elastic IP and is properly attached to the subnets within the VPC.

