Below is the complete Terraform HCL program that creates an Application Load Balancer with a listener and a rule that returns a fixed response. The configuration includes all necessary resources and dependencies as per the provided schema summary.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "example-vpc"
  }
}

resource "aws_subnet" "public" {
  count                   = 2
  vpc_id                  = aws_vpc.main.id
  cidr_block              = cidrsubnet(aws_vpc.main.cidr_block, 8, count.index)
  map_public_ip_on_launch = true

  tags = {
    Name = "example-subnet-${count.index}"
  }
}

resource "aws_lb" "load_balancer" {
  name               = "example-load-balancer"
  internal           = false
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = aws_subnet.public[*].id
  load_balancer_type = "application"

  tags = {
    Name = "example-load-balancer"
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "example-lb-sg"
  description = "Allow HTTP traffic to load balancer"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "example-lb-sg"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, this is a fixed response!"
      status_code  = "200"
    }
  }
}

resource "aws_lb_listener_rule" "fixed_response_rule" {
  listener_arn = aws_lb_listener.listener.arn
  priority     = 100

  action {
    type = "fixed-response"

    fixed_response {
      content_type = "text/plain"
      message_body = "Hello, this is a fixed response!"
      status_code  = "200"
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **VPC and Subnets**: A VPC and two public subnets are created to host the load balancer.
3. **Security Group**: A security group is created to allow HTTP traffic on port 80.
4. **Load Balancer**: An Application Load Balancer is created with the specified subnets and security group.
5. **Listener**: A listener is created on port 80 with a default action that returns a fixed response.
6. **Listener Rule**: A rule is added to the listener that matches requests with the host header `example.com` and returns a fixed response.

This configuration ensures that the load balancer is set up correctly with a fixed response for specific requests.

