Below is a complete Terraform HCL program that creates an AWS Load Balancer with an `authenticate-cognito` action. This configuration includes the necessary Cognito User Pool, User Pool Client, and User Pool Domain.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_cognito_user_pool" "cognito_user_pool" {
  name                     = "example-user-pool"
  auto_verified_attributes = ["email"]
  deletion_protection      = false

  password_policy {
    minimum_length = 8
    require_numbers = true
    require_symbols = true
    require_uppercase = true
    require_lowercase = true
  }

  verification_message_template {
    default_email_option = "CONFIRM_WITH_LINK"
  }
}

resource "aws_cognito_user_pool_client" "cognito_user_pool_client" {
  name         = "example-user-pool-client"
  user_pool_id = aws_cognito_user_pool.cognito_user_pool.id

  allowed_oauth_flows          = ["code"]
  allowed_oauth_scopes         = ["email", "openid", "profile"]
  allowed_oauth_flows_user_pool_client = true
  generate_secret              = true
  callback_urls                = ["https://example.com/callback"]
  logout_urls                  = ["https://example.com/logout"]
}

resource "aws_cognito_user_pool_domain" "cognito_user_pool_domain" {
  domain       = "example-user-pool-domain"
  user_pool_id = aws_cognito_user_pool.cognito_user_pool.id
}

resource "aws_lb" "load_balancer" {
  name               = "example-load-balancer"
  internal           = false
  security_groups    = ["sg-0123456789abcdef0"] # Replace with a valid security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"] # Replace with valid subnet IDs
  enable_http2       = true
  idle_timeout       = 60
  enable_deletion_protection = false

  tags = {
    Name = "example-load-balancer"
  }
}

resource "aws_lb_listener" "lb_listener" {
  load_balancer_arn = aws_lb.load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type = "authenticate-cognito"

    authenticate_cognito {
      user_pool_arn       = aws_cognito_user_pool.cognito_user_pool.arn
      user_pool_client_id = aws_cognito_user_pool_client.cognito_user_pool_client.id
      user_pool_domain    = aws_cognito_user_pool_domain.cognito_user_pool_domain.domain
      session_cookie_name = "AWSELBAuthSessionCookie"
      scope               = "openid email profile"
      session_timeout     = 604800
      on_unauthenticated_request = "authenticate"
    }

    redirect {
      protocol = "HTTPS"
      port     = "443"
      host     = "#{host}"
      path     = "/#{path}"
      query    = "#{query}"
      status_code = "HTTP_302"
    }
  }
}
```

### Notes:
- **Security Groups and Subnets**: Replace `"sg-0123456789abcdef0"` and `["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]` with valid security group and subnet IDs from your AWS environment.
- **Domain**: The `domain` attribute in `aws_cognito_user_pool_domain` must be unique across all AWS accounts and regions.
- **Callback URLs and Logout URLs**: Update these URLs to match your application's endpoints.
- **Region**: The region is set to `us-west-2`. Change it if you need a different region.

