```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lb_oidc_auth_role" {
  name = "lb-oidc-auth-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "elb.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })
}

resource "aws_iam_policy" "lb_oidc_auth_policy" {
  name = "lb-oidc-auth-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "logs:CreateLogGroup",
          "logs:CreateLogStream",
          "logs:PutLogEvents"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "attach_lb_oidc_auth_policy" {
  policy_arn = aws_iam_policy.lb_oidc_auth_policy.arn
  role       = aws_iam_role.lb_oidc_auth_role.name
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  security_groups    = ["sg-0123456789abcdef0"] # Replace with a valid security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"] # Replace with valid subnet IDs
  enable_http2       = true
  idle_timeout       = 60
  enable_deletion_protection = false
}

resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "443"
  protocol          = "HTTPS"
  ssl_policy        = "ELBSecurityPolicy-2016-08"

  default_action {
    type = "authenticate-oidc"
    authenticate_oidc {
      authorization_endpoint = "https://example.com/oauth2/authorize"
      client_id              = "your-client-id"
      client_secret          = "your-client-secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/oauth2/token"
      user_info_endpoint     = "https://example.com/oauth2/userinfo"
      session_cookie_name    = "AWSELBAuthSessionCookie"
      scope                  = "openid"
      session_timeout        = 604800
    }
  }
}

resource "aws_lb_listener_rule" "oidc_auth_rule" {
  listener_arn = aws_lb_listener.alb_listener.arn
  priority     = 100

  action {
    type = "authenticate-oidc"
    authenticate_oidc {
      authorization_endpoint = "https://example.com/oauth2/authorize"
      client_id              = "your-client-id"
      client_secret          = "your-client-secret"
      issuer                 = "https://example.com"
      token_endpoint         = "https://example.com/oauth2/token"
      user_info_endpoint     = "https://example.com/oauth2/userinfo"
      session_cookie_name    = "AWSELBAuthSessionCookie"
      scope                  = "openid"
      session_timeout        = 604800
    }
  }

  condition {
    field  = "host-header"
    values = ["example.com"]
  }
}
```

### Notes:
- Replace `"sg-0123456789abcdef0"` and `"subnet-0123456789abcdef0", "subnet-0123456789abcdef1"` with valid security group and subnet IDs from your AWS account.
- Replace `"https://example.com/oauth2/authorize"`, `"your-client-id"`, `"your-client-secret"`, `"https://example.com"`, `"https://example.com/oauth2/token"`, and `"https://example.com/oauth2/userinfo"` with your actual OIDC provider details.
- The `ssl_policy` attribute in the `aws_lb_listener` resource is set to `"ELBSecurityPolicy-2016-08"`. You can choose a different policy based on your security requirements.

