    Name = "GatewayLoadBalancerSubnet2"
  }
}

resource "aws_lb" "gateway_load_balancer" {
  name               = "GatewayLoadBalancer"
  load_balancer_type = "gateway"
  internal           = true
  subnets = [
    aws_subnet.gateway_load_balancer_subnet_1.id,
    aws_subnet.gateway_load_balancer_subnet_2.id
  ]
  tags = {
    Name = "GatewayLoadBalancer"
  }
}
```

This Terraform configuration creates a VPC with two subnets in different availability zones and then sets up a Gateway Load Balancer using these subnets. The VPC and subnets are configured with reasonable default settings, and the load balancer is set to be internal.

