Below is the complete Terraform HCL program that creates an Application Load Balancer with a Lambda function as the target. The program includes the necessary IAM roles, policies, Lambda function, target group, and listener.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "lambda_execution_role" {
  name = "lambda-execution-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "lambda.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "lambda_basic_execution_policy" {
  policy_arn = "arn:aws:iam::aws:policy/service-role/AWSLambdaBasicExecutionRole"
  role       = aws_iam_role.lambda_execution_role.name
}

resource "aws_lambda_function" "example_lambda_function" {
  function_name = "example-lambda-function"
  role          = aws_iam_role.lambda_execution_role.arn
  handler       = "index.handler"
  runtime       = "python3.8"
  filename      = "lambda_function_payload.zip"

  environment {
    variables = {
      NAME = "World"
    }
  }
}

resource "aws_lb_target_group" "lambda_target_group" {
  name     = "lambda-target-group"
  protocol = "HTTP"

  lambda_multi_value_headers_enabled = true

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }
}

resource "aws_lambda_permission" "allow_load_balancer_to_invoke_lambda" {
  statement_id  = "AllowExecutionFromALB"
  action        = "lambda:InvokeFunction"
  function_name = aws_lambda_function.example_lambda_function.function_name
  principal     = "elasticloadbalancing.amazonaws.com"
  source_arn    = "${aws_lb.application_load_balancer.arn}/*"
}

resource "aws_lb" "application_load_balancer" {
  name               = "application-load-balancer"
  internal           = false
  load_balancer_type = "application"
  security_groups    = ["sg-0123456789abcdef0"] # Replace with a valid security group ID
  subnets            = ["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"] # Replace with valid subnet IDs

  enable_http2 = true

  tags = {
    Name = "Example ALB"
  }
}

resource "aws_lb_listener" "http_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.lambda_target_group.arn
  }
}
```

### Notes:
- **Security Groups and Subnets**: Replace `"sg-0123456789abcdef0"` and `["subnet-0123456789abcdef0", "subnet-0123456789abcdef1"]` with valid security group and subnet IDs from your AWS account.
- **Lambda Function Code**: Ensure that `lambda_function_payload.zip` exists in your working directory and contains the Lambda function code.
- **Region**: The region is set to `us-west-2`. You can change it to any other region supported by AWS.
- **IAM Role and Policy**: The IAM role and policy attachment are created to allow the Lambda function to execute and for the Load Balancer to invoke the Lambda function.

