Below is a complete Terraform HCL program that creates an Application Load Balancer (ALB), a target group, and a listener to route traffic from the ALB to the target group. The program includes all necessary resources and dependencies as per the provided schema summary.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-b"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  security_groups    = [aws_security_group.alb_sg.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  enable_http2       = true
  idle_timeout       = 60
  enable_deletion_protection = false

  tags = {
    Name = "my-alb"
  }
}

resource "aws_lb_target_group" "alb_target_group" {
  name     = "my-alb-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "my-alb-target-group"
  }
}

resource "aws_lb_listener" "alb_listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.alb_target_group.arn
  }
}

resource "aws_security_group" "alb_sg" {
  name        = "alb-sg"
  description = "Security group for ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "alb-sg"
  }
}
```

### Explanation:
- **Provider Configuration**: Configures the AWS provider with the `us-west-2` region.
- **VPC and Subnets**: Creates a VPC and two public subnets in different availability zones.
- **Application Load Balancer (ALB)**: Creates an ALB with HTTP2 enabled, attached to the public subnets, and associated with a security group.
- **Target Group**: Creates a target group for the ALB, specifying the port and protocol, and configuring a basic health check.
- **Listener**: Sets up a listener on port 80 that forwards traffic to the target group.
- **Security Group**: Defines a security group for the ALB allowing HTTP traffic from any IP address (`0.0.0.0/0`) and full egress.

This configuration ensures that the ALB, target group, and listener are correctly set up and interconnected.

