Below is a complete Terraform HCL program that creates an Application Load Balancer (ALB), a Target Group, and attaches them using a Listener. The program includes all necessary resources and dependencies as per the provided schema summary and requirements.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main" {
  cidr_block = "10.0.0.0/16"

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "public_a" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.1.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-a"
  }
}

resource "aws_subnet" "public_b" {
  vpc_id                  = aws_vpc.main.id
  cidr_block              = "10.0.2.0/24"
  map_public_ip_on_launch = true

  tags = {
    Name = "public-subnet-b"
  }
}

resource "aws_lb" "application_load_balancer" {
  name               = "my-application-load-balancer"
  internal           = false
  security_groups    = [aws_security_group.lb_sg.id]
  subnets            = [aws_subnet.public_a.id, aws_subnet.public_b.id]
  enable_http2       = true
  idle_timeout       = 60
  enable_deletion_protection = false

  tags = {
    Name = "my-alb"
  }
}

resource "aws_lb_target_group" "target_group" {
  name     = "my-target-group"
  port     = 80
  protocol = "HTTP"
  vpc_id   = aws_vpc.main.id

  health_check {
    path                = "/"
    interval            = 30
    timeout             = 5
    healthy_threshold   = 5
    unhealthy_threshold = 2
  }

  tags = {
    Name = "my-target-group"
  }
}

resource "aws_lb_listener" "listener" {
  load_balancer_arn = aws_lb.application_load_balancer.arn
  port              = "80"
  protocol          = "HTTP"

  default_action {
    type             = "forward"
    target_group_arn = aws_lb_target_group.target_group.arn
  }
}

resource "aws_security_group" "lb_sg" {
  name        = "lb-sg"
  description = "Allow HTTP traffic to ALB"
  vpc_id      = aws_vpc.main.id

  ingress {
    from_port   = 80
    to_port     = 80
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"]
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "lb-sg"
  }
}
```

### Explanation:
- **Provider Configuration**: Configures the AWS provider with the `us-west-2` region.
- **VPC and Subnets**: Creates a VPC and two public subnets within the VPC.
- **Security Group**: Creates a security group that allows HTTP traffic on port 80.
- **Application Load Balancer (ALB)**: Creates an ALB in the public subnets with HTTP2 enabled.
- **Target Group**: Creates a target group for HTTP traffic on port 80.
- **Listener**: Attaches the target group to the ALB via a listener on port 80.

This configuration ensures that the ALB, Target Group, and Listener are correctly set up and attached, fulfilling the user's requirements.

