Below is a complete Terraform HCL program that creates a basic AWS RDS instance along with the necessary supporting resources such as VPC, subnets, DB subnet group, and security group. The configuration ensures that all dependencies are correctly managed.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "main_vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = "main-vpc"
  }
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-a"
  }
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.main_vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = true

  tags = {
    Name = "subnet-b"
  }
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]

  tags = {
    Name = "rds-subnet-group"
  }
}

resource "aws_security_group" "rds_security_group" {
  vpc_id = aws_vpc.main_vpc.id

  ingress {
    from_port   = 3306
    to_port     = 3306
    protocol    = "tcp"
    cidr_blocks = ["0.0.0.0/0"] # For demonstration purposes; restrict in production
  }

  egress {
    from_port   = 0
    to_port     = 0
    protocol    = "-1"
    cidr_blocks = ["0.0.0.0/0"]
  }

  tags = {
    Name = "rds-security-group"
  }
}

resource "aws_db_instance" "basic_rds_instance" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = "mydb"
  username             = "admin"
  password             = "password123"
  parameter_group_name = "default.mysql8.0"
  skip_final_snapshot  = true
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  vpc_security_group_ids = [aws_security_group.rds_security_group.id]

  tags = {
    Name = "basic-rds-instance"
  }
}
```

### Explanation:
- **Provider Configuration**: Specifies the AWS region (`us-west-2`).
- **VPC**: Creates a VPC with a CIDR block of `10.0.0.0/16`.
- **Subnets**: Creates two subnets (`subnet_a` and `subnet_b`) in different availability zones (`us-west-2a` and `us-west-2b`).
- **DB Subnet Group**: Associates the subnets with the RDS instance.
- **Security Group**: Allows inbound traffic on port 3306 (MySQL) from any IP (`0.0.0.0/0`), which should be restricted in a production environment.
- **RDS Instance**: Creates a MySQL RDS instance with the specified parameters, including storage, engine, instance class, and security group.

This configuration is deployable with Terraform `~> 1.9.8` and `hashicorp/aws ~> 5.75`.

