Below is a complete Terraform HCL program that creates a basic AWS RDS instance with `io1` storage type, along with necessary supporting resources such as VPC, subnets, DB subnet group, and IAM role.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_vpc" "vpc" {
  cidr_block           = "10.0.0.0/16"
  enable_dns_support   = true
  enable_dns_hostnames = true
}

resource "aws_subnet" "subnet_a" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.1.0/24"
  availability_zone       = "us-west-2a"
  map_public_ip_on_launch = true
}

resource "aws_subnet" "subnet_b" {
  vpc_id                  = aws_vpc.vpc.id
  cidr_block              = "10.0.2.0/24"
  availability_zone       = "us-west-2b"
  map_public_ip_on_launch = true
}

resource "aws_db_subnet_group" "rds_subnet_group" {
  name       = "rds-subnet-group"
  subnet_ids = [aws_subnet.subnet_a.id, aws_subnet.subnet_b.id]
}

resource "aws_iam_policy" "rds_policy" {
  name        = "rds-policy"
  description = "Policy for RDS instance"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds:*"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "rds_role" {
  name               = "rds-role"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [aws_iam_policy.rds_policy.arn]
}

resource "aws_db_instance" "rds_instance" {
  allocated_storage    = 20
  engine               = "mysql"
  engine_version       = "8.0"
  instance_class       = "db.t3.micro"
  name                 = "mydb"
  username             = "admin"
  password             = "password123"
  parameter_group_name = "default.mysql8.0"
  skip_final_snapshot  = true
  db_subnet_group_name = aws_db_subnet_group.rds_subnet_group.name
  storage_type         = "io1"
  iops                 = 1000
}
```

### Explanation:
- **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
- **VPC**: A VPC with a CIDR block of `10.0.0.0/16` is created.
- **Subnets**: Two subnets (`subnet_a` and `subnet_b`) are created within the VPC, each in different availability zones (`us-west-2a` and `us-west-2b`).
- **DB Subnet Group**: A DB subnet group is created using the two subnets.
- **IAM Policy and Role**: An IAM policy granting RDS-related actions is created, and an IAM role is created with this policy attached, assuming the RDS service can assume this role.
- **RDS Instance**: An RDS instance is created with MySQL engine, `io1` storage type, and 1000 IOPS. The instance is placed in the DB subnet group created earlier. The `skip_final_snapshot` option is set to `true` to avoid snapshot creation on deletion for simplicity.

