Below is the complete Terraform HCL program that creates an AWS S3 bucket, an IAM role with the necessary permissions to access the S3 bucket, and an RDS instance restored from a backup file stored in the S3 bucket.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_s3_bucket" "database_backup_bucket" {
  bucket = "my-database-backup-bucket-unique-name"
  acl    = "private"

  tags = {
    Name        = "DatabaseBackupBucket"
    Environment = "production"
  }
}

resource "aws_iam_role" "rds_restore_role" {
  name = "rds-restore-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
      }
    ]
  })

  tags = {
    Name        = "RDSRestoreRole"
    Environment = "production"
  }
}

resource "aws_iam_policy" "s3_access_policy" {
  name = "s3-access-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "s3:GetObject",
          "s3:ListBucket"
        ]
        Effect   = "Allow"
        Resource = [
          "${aws_s3_bucket.database_backup_bucket.arn}",
          "${aws_s3_bucket.database_backup_bucket.arn}/*"
        ]
      }
    ]
  })

  tags = {
    Name        = "S3AccessPolicy"
    Environment = "production"
  }
}

resource "aws_iam_role_policy_attachment" "attach_s3_access_policy" {
  policy_arn = aws_iam_policy.s3_access_policy.arn
  role       = aws_iam_role.rds_restore_role.name
}

resource "aws_db_instance" "restored_database" {
  instance_class = "db.t3.micro"
  db_name          = "restored_db"
  engine           = "mysql"
  username         = "admin"
  password         = "securepassword123"
  skip_final_snapshot = true

  s3_import {
    bucket_name     = aws_s3_bucket.database_backup_bucket.bucket
    ingestion_role  = aws_iam_role.rds_restore_role.arn
    source_engine   = "mysql"
    source_engine_version = "5.7"
    bucket_prefix   = "backups/"
  }

  tags = {
    Name        = "RestoredDatabase"
    Environment = "production"
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **S3 Bucket**: An S3 bucket named `my-database-backup-bucket-unique-name` is created with private ACL.
3. **IAM Role**: An IAM role named `rds-restore-role` is created with a trust relationship allowing RDS to assume the role.
4. **IAM Policy**: An IAM policy named `s3-access-policy` is created to grant read access to the S3 bucket.
