Below is a complete Terraform HCL program that creates an AWS RDS database instance with storage autoscaling enabled. The program includes the necessary IAM role and policy to support the autoscaling feature.

```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_policy" "database_policy" {
  name        = "database-autoscale-policy"
  description = "Policy for RDS database autoscaling"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Action = [
          "rds:DescribeDBInstances",
          "rds:ModifyDBInstance"
        ]
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role" "database_role" {
  name               = "database-autoscale-role"
  description        = "Role for RDS database autoscaling"
  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Effect = "Allow"
        Principal = {
          Service = "rds.amazonaws.com"
        }
        Action = "sts:AssumeRole"
      }
    ]
  })

  managed_policy_arns = [aws_iam_policy.database_policy.arn]
}

resource "aws_db_instance" "autoscaling_database" {
  instance_class            = "db.t3.micro"
  allocated_storage         = 20
  db_subnet_group_name      = "default" # Ensure this subnet group exists in your VPC
  vpc_security_group_ids    = ["sg-0123456789abcdef0"] # Replace with a valid security group ID
  multi_az                  = false
  storage_type              = "gp2"
  skip_final_snapshot       = true
  deletion_protection       = false
  iam_database_authentication_enabled = false
  custom_iam_instance_profile = aws_iam_role.database_role.name

  # Storage autoscaling configuration
  scaling_configuration {
    auto_pause   = false
    max_capacity = 100
    min_capacity = 20
    seconds_until_auto_pause = 300
    timeout_action           = "RollbackCapacityChange"
  }
}
```

### Explanation:
1. **Provider Configuration**: The AWS provider is configured to use the `us-west-2` region.
2. **IAM Policy**: An IAM policy named `database-autoscale-policy` is created with permissions to describe and modify RDS instances.
3. **IAM Role**: An IAM role named `database-autoscale-role` is created with the trust relationship to be assumed by RDS and attached with the previously created policy.
4. **DB Instance**: An RDS DB instance named `autoscaling_database` is created with the `db.t3.micro` instance class and 20 GB of initial storage. It uses the `default` DB subnet group and a placeholder security group ID (`sg-0123456789abcdef0`). The `custom_iam_instance_profile` attribute is set to the name of the IAM role created earlier. The `scaling_configuration` block configures storage autoscaling with a minimum capacity of 20 GB and a maximum capacity of 100 GB.

Make sure to replace the `db_subnet_group_name` and `vpc_security_group_ids` with valid values from your AWS environment.

