```hcl
provider "aws" {
  region = "us-west-2"
}

resource "aws_iam_role" "backup_role" {
  name = "backup-role"

  assume_role_policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = "sts:AssumeRole"
        Effect = "Allow"
        Principal = {
          Service = "backup.amazonaws.com"
        }
      }
    ]
  })
}

resource "aws_iam_policy" "backup_policy" {
  name = "backup-policy"

  policy = jsonencode({
    Version = "2012-10-17"
    Statement = [
      {
        Action = [
          "ec2:DescribeVolumes",
          "ec2:DescribeSnapshots",
          "ec2:CreateTags",
          "ec2:CreateVolume",
          "ec2:CreateSnapshot",
          "efs:DescribeFileSystems",
          "efs:DescribeMountTargets",
          "efs:Backup",
          "backup:StartBackupJob",
          "backup:PutBackupVaultAccessPolicy",
          "backup:GetBackupVaultAccessPolicy",
          "backup:DeleteBackupVaultAccessPolicy",
          "backup:UpdateRecoveryPointLifecycle",
          "backup:GetRecoveryPointRestoreMetadata",
          "backup:GetRecoveryPointMetadata",
          "backup:RestoreRecoveryPoint",
          "backup:ListRecoveryPointsByBackupVault",
          "backup:ListBackupPlanTemplates",
          "backup:ListBackupPlans",
          "backup:ListBackupJobs",
          "backup:ListRecoveryPointsByResource",
          "backup:ListProtectedResources",
          "backup:ListBackupVaults",
          "backup:DescribeBackupVault",
          "backup:DescribeRecoveryPoint",
          "backup:DescribeBackupPlan",
          "backup:DescribeCopyJob",
          "backup:DescribeFramework",
          "backup:DescribeProtectedResource",
          "backup:DescribeBackupJob",
          "backup:DescribeBackupSelection",
          "backup:DescribeBackupPlanVersion",
          "backup:DescribeRegionSettings",
          "backup:DescribeRestoreJob",
          "backup:GetSupportedResourceTypes"
        ]
        Effect = "Allow"
        Resource = "*"
      }
    ]
  })
}

resource "aws_iam_role_policy_attachment" "backup_policy_attachment" {
  policy_arn = aws_iam_policy.backup_policy.arn
  role       = aws_iam_role.backup_role.name
}

resource "aws_backup_vault" "backup_vault" {
  name = "my-backup-vault"
}

resource "aws_backup_plan" "backup_plan" {
  name = "my-backup-plan"

  rule {
    rule_name         = "daily-backup"
    target_vault_name = aws_backup_vault.backup_vault.name
    schedule          = "cron(0 12 * * ? *)"
    start_window      = 3600
    completion_window = 43200
    enable_continuous_backup = false

    recovery_point_tags = {
      Name = "DailyBackup"
    }
  }
}

resource "aws_efs_file_system" "efs_file_system" {
  creation_token = "my-efs-creation-token"
  encrypted      = true
  performance_mode = "generalPurpose"
  throughput_mode  = "bursting"

  tags = {
    Name = "MyEFS"
  }
}

resource "aws_backup_selection" "backup_selection" {
  iam_role_arn = aws_iam_role.backup_role.arn
  name         = "my-backup-selection"
  plan_id      = aws_backup_plan.backup_plan.id

  resources = [aws_efs_file_system.efs_file_system.arn]
}
```

This Terraform configuration sets up an AWS EFS file system with automatic backups enabled using AWS Backup. It includes the necessary IAM roles and policies, a backup vault, a backup plan, and a backup selection to ensure the EFS file system is backed up daily.

