Below is the complete Terraform HCL program that sets up a dedicated-tenancy AWS VPC with DNS support and hostnames enabled, an internet gateway, and a route table for outbound internet access, all tagged with a variable name. The program includes all necessary resources and dependencies as per the provided prompt and schema summary.

```hcl
provider "aws" {
  region = "us-west-2"
}

variable "vpc_name" {
  description = "Name tag for the VPC and related resources"
  default     = "dedicated-tenancy-vpc"
}

resource "aws_vpc" "dedicated_tenancy_vpc" {
  cidr_block           = "10.0.0.0/16"
  instance_tenancy     = "dedicated"
  enable_dns_support   = true
  enable_dns_hostnames = true

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_internet_gateway" "vpc_internet_gateway" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route_table" "internet_access_route_table" {
  vpc_id = aws_vpc.dedicated_tenancy_vpc.id

  tags = {
    Name = var.vpc_name
  }
}

resource "aws_route" "internet_route" {
  route_table_id         = aws_route_table.internet_access_route_table.id
  destination_cidr_block = "0.0.0.0/0"
  gateway_id             = aws_internet_gateway.vpc_internet_gateway.id
}

resource "aws_main_route_table_association" "main_route_table_association" {
  vpc_id         = aws_vpc.dedicated_tenancy_vpc.id
  route_table_id = aws_route_table.internet_access_route_table.id
}
```

This Terraform configuration creates a dedicated-tenancy VPC with DNS support and hostnames enabled, an internet gateway, and a route table configured for outbound internet access. All resources are tagged with the name specified in the `vpc_name` variable, which has a default value of "dedicated-tenancy-vpc". The configuration is set to deploy in the `us-west-2` region.

